import { defaultContainers, sampleCargo, defaultSettings, presetSettings, packagingPresets } from './defaults.js'
import { boxVolumeM3, packedDimensions, packedWeightKg, optimizePacking } from './packing.js'

const STORAGE_KEY='container-fit-project-v9'
const OLD_STORAGE_KEYS=['container-fit-project-v8','container-fit-project-v7','container-fit-project-v6','container-fit-project-v5','container-fit-project-v4','container-fit-project-v3','container-fit-project-v2','container-fit-project-v1']
const $=(sel,root=document)=>root.querySelector(sel)
const $$=(sel,root=document)=>[...root.querySelectorAll(sel)]
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':'&quot;',"'":'&#39;'}[c]))
const xmlEsc=(s='')=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':'&quot;',"'":'&apos;'}[c]))
const clone=x=>JSON.parse(JSON.stringify(x))
const num=(v,f=0)=>Number.isFinite(Number(v))?Number(v):f
const fmt=n=>num(n).toLocaleString('ko-KR',{maximumFractionDigits:1})
const fmtInt=n=>Math.round(num(n)).toLocaleString('ko-KR')
const pct=v=>`${Math.max(0,num(v)*100).toFixed(1)}%`
const packagePreset=(type)=>packagingPresets[type]||packagingPresets.bare

const icons={
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', calc:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2m4 0h2M8 15h2m4 0h2M8 19h8"/>',
 container:'<path d="M3 6.5 12 3l9 3.5v11L12 21l-9-3.5v-11Z"/><path d="M12 3v18M3 6.5l9 3.5 9-3.5M7 8v11M17 8v11"/>', box:'<path d="m21 8-9-5-9 5 9 5 9-5Z"/><path d="m3 8 9 5v8l-9-5V8Zm18 0-9 5v8l9-5V8Z"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-4v-.08A1.7 1.7 0 0 0 8.97 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.56-1.03H3v-4h.08A1.7 1.7 0 0 0 4.6 8.94a1.7 1.7 0 0 0-.34-1.88L4.2 7l2.83-2.83.06.06A1.7 1.7 0 0 0 8.97 4.6 1.7 1.7 0 0 0 10 3.05V3h4v.08a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06L19.8 7l-.06.06a1.7 1.7 0 0 0-.34 1.88 1.7 1.7 0 0 0 1.56 1.03H21v4h-.08A1.7 1.7 0 0 0 19.4 15Z"/>',
 layers:'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>', upload:'<path d="M12 3v12m0-12-4 4m4-4 4 4"/><path d="M5 13v6h14v-6"/>', download:'<path d="M12 3v12m0 0-4-4m4 4 4-4"/><path d="M5 19h14"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', edit:'<path d="m4 20 4.5-1 10-10-3.5-3.5-10 10L4 20Z"/><path d="m13.5 6.5 3.5 3.5"/>', trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7m4 4v6m4-6v6"/>',
 save:'<path d="M5 3h12l2 2v16H5V3Z"/><path d="M8 3v6h8V3M8 21v-8h8v8"/>', reset:'<path d="M4 11a8 8 0 1 1 2 5.5M4 11V6m0 5h5"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>', check:'<path d="m5 12 4 4L19 6"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>', up:'<path d="m18 15-6-6-6 6"/>', down:'<path d="m6 9 6 6 6-6"/>', spark:'<path d="m12 3 1.6 4.4L18 9l-4.4 1.6L12 15l-1.6-4.4L6 9l4.4-1.6L12 3Z"/><path d="m19 15 .8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8L19 15Z"/>',
 alert:'<path d="M12 3 2.5 20h19L12 3Z"/><path d="M12 9v5m0 3h.01"/>', package:'<path d="M4 8.5 12 4l8 4.5v9L12 22l-8-4.5v-9Z"/><path d="M12 13 4 8.5M12 13l8-4.5M12 13v9M8 6l8 4.5"/>',
 ruler:'<path d="M4 19 19 4l2 2L6 21l-2-2Z"/><path d="m15 6 3 3M12 9l2 2M9 12l3 3M6 15l2 2"/>', file:'<path d="M6 3h8l4 4v14H6V3Z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>', image:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 15-5-5L5 20"/>', sheet:'<path d="M5 3h14v18H5zM9 3v18M5 8h14M5 13h14M5 18h14"/>', eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>'
}
const icon=(name,size=18)=>`<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`

function normalizePackaging(p){
  const type=p?.type&&packagingPresets[p.type]?p.type:'bare',base=packagePreset(type)
  return {...base,...(p||{}),type,label:p?.label||base.label}
}
function legacyOrientationRules(mode){
  if(mode==='free')return {rotate90:true,layWidth:true,layLength:true}
  if(mode==='upright')return {rotate90:true,layWidth:false,layLength:false}
  if(mode==='layWidth')return {rotate90:true,layWidth:true,layLength:false}
  if(mode==='layLength')return {rotate90:true,layWidth:false,layLength:true}
  return {rotate90:false,layWidth:false,layLength:false}
}
function normalizeCargoItem(item,{resetLegacyOrientation=false}={}){
  const orientationRules=resetLegacyOrientation?{rotate90:false,layWidth:false,layLength:false}:item.orientationRules?{rotate90:item.orientationRules.rotate90===true,layWidth:item.orientationRules.layWidth===true,layLength:item.orientationRules.layLength===true}:legacyOrientationRules(item.rotation||'locked')
  const canSupportCargo=(item.canSupportCargo??item.stackable)===true
  return {...item,length:num(item.length,1),width:num(item.width,1),height:num(item.height,1),weightKg:num(item.weightKg),quantity:Math.max(1,Math.floor(num(item.quantity,1))),rotation:'locked',orientationRules,canBeStacked:item.canBeStacked===true,canSupportCargo,stackable:canSupportCargo,maxStackLayers:Math.max(1,Math.floor(num(item.maxStackLayers,canSupportCargo?2:1))),sameCargoStackOnly:item.sameCargoStackOnly!==false,canBeNested:item.canBeNested===true,color:item.color||'#2f80ed',packaging:normalizePackaging(item.packaging),innerSpace:{enabled:Boolean(item.innerSpace?.enabled),length:num(item.innerSpace?.length),width:num(item.innerSpace?.width),height:num(item.innerSpace?.height),access:['top','side','full'].includes(item.innerSpace?.access)?item.innerSpace.access:'top',maxPayloadKg:num(item.innerSpace?.maxPayloadKg)}}
}
function orientationMode(item){
  const r=item.orientationRules||legacyOrientationRules(item.rotation)
  if(r.layWidth||r.layLength)return 'all'
  if(r.rotate90)return 'upright'
  return 'fixed'
}
function orientationRulesForMode(mode){
  if(mode==='all')return {rotate90:true,layWidth:true,layLength:true}
  if(mode==='upright')return {rotate90:true,layWidth:false,layLength:false}
  return {rotate90:false,layWidth:false,layLength:false}
}
function directionChangeAllowed(item){
  const r=item.orientationRules||legacyOrientationRules(item.rotation)
  return Boolean(r.rotate90||r.layWidth||r.layLength)
}
function orientationSummary(item){const m=orientationMode(item);return m==='all'?'3축 회전 허용':m==='upright'?'수직 유지 · 평면 회전':'기본 자세 고정'}
function simpleStackAllowed(item){return item.canBeStacked===true||item.canSupportCargo===true}
function stackRole(item){const up=item.canBeStacked===true,support=item.canSupportCargo===true;return up&&support?'both':up?'upper':support?'support':'none'}
function stackRoleLabel(role){return role==='upper'?'상부 적재 가능':role==='support'?'하중 지지 가능':role==='both'?'상·하 적층 가능':'적층 불가'}
function stackRoleFlags(role){return {canBeStacked:role==='upper'||role==='both',canSupportCargo:role==='support'||role==='both'}}
function directionModeLabel(mode){return mode==='all'?'3축 회전 · 눕힘 허용':mode==='upright'?'수직 유지 · 90° 회전':'기본 자세 고정'}

function normalizeSettings(s={}){
  const oldWall=num(s.wallClearance,-1)
  const base={...defaultSettings,...s}
  if(oldWall>=0){base.sideClearance=oldWall;base.rearClearance=oldWall;base.doorClearance=oldWall;base.ceilingClearance=oldWall;delete base.wallClearance}
  if(base.verticalGap==null)base.verticalGap=0
  if(base.stackItemGap==null)base.stackItemGap=0
  if(base.blockContact==null)base.blockContact=false
  if(!['auto','block','fewest','prefer40','prefer20','utilization','only40','only20'].includes(base.optimizationGoal))base.optimizationGoal='auto'
  return base
}

let state={containers:clone(defaultContainers),cargo:[],settings:clone(defaultSettings),result:null,openResult:0,mobileNav:false,modal:null,viewMode:'iso',calculating:false,calcMessage:''}
try{
  const current=localStorage.getItem(STORAGE_KEY),legacy=OLD_STORAGE_KEYS.map(k=>localStorage.getItem(k)).find(Boolean);const saved=JSON.parse(current||legacy||'null')
  if(saved?.containers&&saved?.cargo&&saved?.settings){const migrated=!current;state={...state,containers:saved.containers,cargo:saved.cargo.map(x=>normalizeCargoItem(x,{resetLegacyOrientation:num(saved.version)<4})),settings:normalizeSettings({...saved.settings,...(migrated&&num(saved.version)<4?{optimizationGoal:'auto'}:{})})}}
}catch{}
const persist=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify({version:9,containers:state.containers,cargo:state.cargo,settings:state.settings}))}catch{}}

function toast(message,kind='info'){
  let stack=$('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.append(stack)}
  const el=document.createElement('div');el.className=`toast toast--${kind}`;el.innerHTML=`${icon(kind==='success'?'check':kind==='error'?'close':'info',17)}<span>${esc(message)}</span>`;while(stack.children.length>=2)stack.firstElementChild?.remove();stack.append(el);setTimeout(()=>el.remove(),3000)
}
function optimizationLabel(goal){return goal==='block'?'블록화·적층 우선':goal==='fewest'?'대수 최소 + 잔량 최소':goal==='prefer40'?'40ft 중심 + 잔량 최적':goal==='prefer20'?'20ft 중심':goal==='only40'?'40ft만 사용':goal==='only20'?'20ft만 사용':goal==='utilization'?'활용률 우선':'자동 추천'}
function resultGoalLabel(r){const requested=r?.requestedGoal||state.settings.optimizationGoal||'auto';return requested==='auto'?'자동 추천 · 블록화/대수 최소':optimizationLabel(requested)}
function accessLabel(a){return a==='top'?'상부 개방':a==='side'?'측면 개방':'완전 개방'}
function unitCount(){return state.cargo.reduce((s,c)=>s+Math.max(0,Math.floor(c.quantity)),0)}
function totalRawVolume(){return state.cargo.reduce((s,c)=>s+boxVolumeM3(c.length,c.width,c.height)*c.quantity,0)}
function totalPackedVolume(){return state.cargo.reduce((s,c)=>{const d=packedDimensions(c);return s+boxVolumeM3(d.length,d.width,d.height)*c.quantity},0)}
function totalWeight(){return state.cargo.reduce((s,c)=>s+packedWeightKg(c)*c.quantity,0)}
function packagingAddedVolume(){return Math.max(0,totalPackedVolume()-totalRawVolume())}

function inputDiagnosticsHtml(){
  if(!state.cargo.length)return''
  const total=Math.max(.000001,totalPackedVolume())
  const ranked=state.cargo.map(c=>{const d=packedDimensions(c),v=boxVolumeM3(d.length,d.width,d.height)*c.quantity;return{c,d,v,share:v/total}}).sort((a,b)=>b.v-a.v)
  const top=ranked[0],fixed=state.cargo.filter(c=>{const r=c.orientationRules||legacyOrientationRules(c.rotation);return !r.rotate90&&!r.layWidth&&!r.layLength}).length,zeroWeight=state.cargo.filter(c=>packedWeightKg(c)<=0).length
  const directionAllowed=state.cargo.filter(directionChangeAllowed).length
  const alerts=[]
  if(top&&top.share>=.5&&top.c.quantity>=10)alerts.push(`<div class="diagnostic diagnostic--warn">${icon('alert',18)}<div><strong>대수 급증 원인 후보: ${esc(top.c.name)} ${top.c.quantity}개</strong><span>이 품목만 포장 후 총 체적의 ${(top.share*100).toFixed(1)}% (${top.v.toFixed(2)} m³)를 차지합니다. CAD의 Set 수, 실제 포장 단위 수, 적층 단수가 같은 의미인지 확인하세요.</span></div></div>`)
  if(fixed)alerts.push(`<div class="diagnostic">${icon('ruler',18)}<div><strong>기본 자세 고정 품목 ${fixed}종</strong><span>안전 기본값입니다. 실제 운송에서 자세 변경이 가능한 품목만 회전 조건을 완화하세요.</span></div></div>`)
  if(directionAllowed)alerts.push(`<div class="diagnostic diagnostic--warn">${icon('alert',18)}<div><strong>방향 변경 허용 품목 ${directionAllowed}종</strong><span>계산기는 체크한 품목만 L/W/H 축을 바꾼 6개 직교 방향까지 자동 비교합니다. 눕힘이 위험한 장비는 체크하지 마세요.</span></div></div>`)
  const upperAllowed=state.cargo.filter(c=>c.canBeStacked).length,supportAllowed=state.cargo.filter(c=>c.canSupportCargo).length
  if(directionAllowed&&!upperAllowed)alerts.push(`<div class="diagnostic diagnostic--warn">${icon('layers',18)}<div><strong>방향 변경만으로는 상부 공간을 사용하지 않습니다.</strong><span>CAD처럼 아래 블록 위에 화물을 올리려면 해당 품목의 ‘적층 가능’을 켜세요. 블록 최적화가 하부/상부 역할을 자동 조합합니다.</span></div></div>`)
  if(upperAllowed&&!supportAllowed)alerts.push(`<div class="diagnostic diagnostic--warn">${icon('layers',18)}<div><strong>적층 조건을 확인하세요.</strong><span>상부 적재 후보는 있으나 지지 가능한 하부 블록이 없습니다. 적층 가능한 품목을 함께 지정하거나 상세 조건을 확인하세요.</span></div></div>` )
  if(state.cargo.some(c=>c.canBeStacked||c.canSupportCargo))alerts.push(`<div class="diagnostic">${icon('layers',18)}<div><strong>상부 공간 적재 조건 사용 중</strong><span>적층 가능으로 체크한 품목끼리는 하부/상부 역할을 자동 조합하여 CAD처럼 빈 상부 공간을 우선 사용합니다.</span></div></div>`)
  if(zeroWeight)alerts.push(`<div class="diagnostic">${icon('info',18)}<div><strong>중량 미입력 ${zeroWeight}종</strong><span>공간 기준 대수는 계산되지만 중량·무게중심·바닥하중 결과는 실제 중량 입력 전까지 참고용입니다.</span></div></div>`)
  return `<section class="input-diagnostics"><div class="input-diagnostics__head"><strong>입력 검증</strong><span>수량·회전·적층 조건이 대수와 배치에 미치는 영향을 계산 전에 확인합니다.</span></div>${alerts.join('')}</section>`
}

function containerIllustration(c){
  const ratio=Math.min(2.8,Math.max(1.4,c.length/Math.max(1,c.width)))
  const x2=48+ratio*20
  return `<svg class="container-illustration" viewBox="0 0 160 74" aria-hidden="true"><defs><linearGradient id="cg-${esc(c.id)}" x1="0" x2="1"><stop offset="0" stop-color="#e8f3fc"/><stop offset="1" stop-color="#bfdcf1"/></linearGradient></defs><path d="M20 50V22l${x2-20} -8v28l-${x2-20} 8Z" fill="url(#cg-${esc(c.id)})" stroke="#5f8bae"/><path d="M${x2} 14l16 8v28l-16-8Z" fill="#a6cae4" stroke="#5f8bae"/><path d="M20 22l${x2-20} -8 16 8-${x2-20} 8Z" fill="#f7fbfe" stroke="#5f8bae"/>${Array.from({length:6},(_,i)=>{const x=28+i*(x2-30)/6;return `<path d="M${x.toFixed(1)} 20v27" stroke="#8cb4d0" stroke-width=".7"/>`}).join('')}<path d="M${x2+4} 24v23M${x2+10} 27v23" stroke="#6f98b6" stroke-width=".8"/></svg>`
}

function containerCards(){return state.containers.map(c=>`<article class="container-card ${c.enabled?'is-selected':''}"><button class="container-card__toggle" data-action="toggle-container" data-id="${esc(c.id)}" aria-pressed="${c.enabled}"><span class="select-dot">${c.enabled?icon('check',14):''}</span>${containerIllustration(c)}<div class="container-card__title"><strong>${esc(c.name)}</strong><span>${esc(c.shortName||'CUSTOM')}</span></div><small>내측 ${fmtInt(c.length)} × ${fmtInt(c.width)} × ${fmtInt(c.height)} mm</small><small>문 ${c.doorWidth?fmtInt(c.doorWidth):'-'} × ${c.doorHeight?fmtInt(c.doorHeight):'-'} mm</small><div class="container-card__stats"><span><b>${num(c.nominalVolumeM3,boxVolumeM3(c.length,c.width,c.height)).toFixed(1)}</b> m³</span><span><b>${fmtInt(c.maxPayloadKg)}</b> kg</span></div></button><div class="container-card__actions"><button data-action="edit-container" data-id="${esc(c.id)}">${icon('edit',14)} 수정</button>${c.custom?`<button class="danger-link" data-action="delete-container" data-id="${esc(c.id)}">${icon('trash',14)} 삭제</button>`:''}</div></article>`).join('')}

function cargoRows(){return state.cargo.map(item=>{const d=packedDimensions(item),pw=packedWeightKg(item),p=item.packaging||normalizePackaging(),dir=orientationMode(item),role=stackRole(item);return `<tr>
<td><div class="cargo-name"><i style="background:${esc(item.color)}"></i><div><strong>${esc(item.name)}</strong><small>${fmtInt(item.length)} × ${fmtInt(item.width)} × ${fmtInt(item.height)} mm · ${item.canBeNested?'내부 삽입 가능':'일반 화물'}</small></div></div></td>
<td><div class="packed-cell"><span class="package-chip">${esc(p.short||p.label)}</span><strong>${fmtInt(d.length)} × ${fmtInt(d.width)} × ${fmtInt(d.height)}</strong><small>${boxVolumeM3(d.length,d.width,d.height).toFixed(3)} m³/개 · ${fmt(pw)} kg</small></div></td>
<td><div class="inline-number"><input data-cargo-quantity="${esc(item.id)}" type="number" min="1" step="1" value="${Math.max(1,Math.floor(item.quantity))}" aria-label="${esc(item.name)} 수량"><span>개</span></div></td>
<td><div class="quick-pack-rules quick-pack-rules--selects"><label class="quick-rule-select"><span>회전 조건</span><select data-cargo-orientation-mode="${esc(item.id)}" aria-label="${esc(item.name)} 회전 조건" title="운송 중 허용되는 자세 범위"><option value="fixed" ${dir==='fixed'?'selected':''}>기본 자세 고정</option><option value="upright" ${dir==='upright'?'selected':''}>수직 유지 · 90° 회전</option><option value="all" ${dir==='all'?'selected':''}>3축 회전 · 눕힘 허용</option></select></label><label class="quick-rule-select"><span>적층 조건</span><select data-cargo-stack-role="${esc(item.id)}" aria-label="${esc(item.name)} 적층 조건" title="다른 화물과의 상하 적층 가능 범위"><option value="none" ${role==='none'?'selected':''}>적층 불가</option><option value="upper" ${role==='upper'?'selected':''}>상부 적재 가능</option><option value="support" ${role==='support'?'selected':''}>하중 지지 가능</option><option value="both" ${role==='both'?'selected':''}>상·하 적층 가능</option></select></label></div></td>
<td>${item.innerSpace?.enabled?`<div class="inner-cell"><span class="status-chip status-chip--accent">${accessLabel(item.innerSpace.access)}</span><strong>${fmtInt(item.innerSpace.length)} × ${fmtInt(item.innerSpace.width)} × ${fmtInt(item.innerSpace.height)}</strong><small>${boxVolumeM3(item.innerSpace.length,item.innerSpace.width,item.innerSpace.height).toFixed(3)} m³</small></div>`:'<span class="muted">미사용</span>'}</td>
<td class="align-right"><div class="row-actions"><button data-action="edit-cargo" data-id="${esc(item.id)}" aria-label="${esc(item.name)} 상세 수정">${icon('edit',16)}</button><button class="danger" data-action="delete-cargo" data-id="${esc(item.id)}" aria-label="${esc(item.name)} 삭제">${icon('trash',16)}</button></div></td></tr>`}).join('')}
function packagingCards(){return Object.entries(packagingPresets).map(([id,p])=>`<article class="package-option"><div class="package-option__icon">${id==='bare'?icon('box',22):id==='steelFrame'?icon('layers',22):icon('package',22)}</div><div><strong>${esc(p.label)}</strong><p>${esc(p.description)}</p><small>기본 추가 외형 L +${fmtInt(p.addLength)} · W +${fmtInt(p.addWidth)} · H +${fmtInt(p.addHeight)} mm / 자중 +${fmt(p.tareWeightKg)} kg</small></div><button class="button button--soft button--small" data-action="add-cargo-with-package" data-id="${id}">이 방식으로 화물 추가</button></article>`).join('')}
function presetCards(){const rows=[['dense','최대 밀도','여유 거의 없이 이론 최대치','개념 검토용'],['cad','도면 밀착 블록','밀착·적층 블록을 우선 반영','사용자 CAD와 유사한 배치'],['practical','실무 기본','기본 작업 여유 반영','일반 출하 시작값'],['safe','안전 여유','취급 공간 확대','대형·취급 민감 화물']];return rows.map(([id,title,desc,foot])=>`<button class="preset-card ${state.settings.preset===id?'is-selected':''}" data-action="preset" data-id="${id}"><span class="radio-dot"></span><strong>${title}</strong><span>${desc}</span><small>${foot}</small></button>`).join('')}
function optimizationCards(){const rows=[['auto','자동 블록 최적화','허용한 방향·적층을 모두 조합해 블록 밀도와 대수를 함께 최적화','CAD처럼 하부 블록 → 상부 빈 공간을 먼저 채움'],['block','블록화 우선','상부 적층과 연속 배치를 최대한 활용','잔량을 마지막 컨테이너로 몰아 최소화'],['fewest','대수 최소','최소 대수 후 잔량 컨테이너까지 축소','컨테이너 수를 가장 먼저 줄임'],['prefer40','40ft 중심','주력은 40ft, 마지막 잔량은 20ft도 허용','불필요한 40ft 잔량 사용 방지'],['prefer20','20ft 중심','대수 증가를 억제하면서 20ft 활용','소량 분할 출하용'],['only40','40ft만 사용','20ft를 사용하지 않음','규격 통일이 반드시 필요할 때'],['only20','20ft만 사용','40ft를 사용하지 않음','현장 제약이 있을 때']];return rows.map(([id,title,desc,foot])=>`<button class="preset-card optimization-card ${state.settings.optimizationGoal===id?'is-selected':''}" data-action="optimization-goal" data-id="${id}"><span class="radio-dot"></span><strong>${title}</strong><span>${desc}</span><small>${foot}</small></button>`).join('')}
function containerTypeSummary(types={}){return Object.entries(types).map(([k,v])=>`${k} ${v}대`).join(' + ')||'-'}
function alternativesHtml(r){if(!r.alternatives?.length||r.alternatives.length<2)return '';return `<div class="alternative-plans"><div class="alternative-plans__head"><strong>전략별 비교 결과</strong><span>같은 화물을 서로 다른 컨테이너 선정 목표로 계산했습니다. 원하는 안을 누르면 그 전략으로 다시 계산합니다.</span></div><div class="alternative-grid">${r.alternatives.map(a=>`<button class="alternative-card ${a.goal===(r.requestedGoal==='auto'?'block':r.requestedGoal)?'is-selected':''}" data-action="goal-and-calculate" data-id="${a.goal}"><span>${optimizationLabel(a.goal)}</span><strong>${a.containerCount}대</strong><small>${containerTypeSummary(a.types)}</small><em>공간 활용률 ${pct(a.overallUtilization)}${a.unpackedCount?` · 미적재 ${a.unpackedCount}`:''}</em></button>`).join('')}</div></div>`}

function shade(hex,amt){let c=String(hex||'#2f80ed').replace('#','');if(c.length===3)c=c.split('').map(x=>x+x).join('');const n=parseInt(c,16)||0,r=Math.min(255,Math.max(0,(n>>16)+amt)),g=Math.min(255,Math.max(0,((n>>8)&255)+amt)),b=Math.min(255,Math.max(0,(n&255)+amt));return `rgb(${r},${g},${b})`}
function isoProject(x,y,z){return {x:(x-y)*.82,y:(x+y)*.34-z}}
function isoBox(p,scale){
  const pr=(x,y,z)=>{const q=isoProject(x,y,z);return{x:q.x*scale,y:q.y*scale}},poly=a=>a.map(v=>`${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ')
  const A=pr(p.x,p.y,p.z),B=pr(p.x+p.length,p.y,p.z),C=pr(p.x+p.length,p.y+p.width,p.z),D=pr(p.x,p.y+p.width,p.z),AT=pr(p.x,p.y,p.z+p.height),BT=pr(p.x+p.length,p.y,p.z+p.height),CT=pr(p.x+p.length,p.y+p.width,p.z+p.height),DT=pr(p.x,p.y+p.width,p.z+p.height)
  return `<g class="cargo-cube"><polygon points="${poly([A,B,BT,AT])}" fill="${shade(p.color,-18)}"/><polygon points="${poly([B,C,CT,BT])}" fill="${shade(p.color,-34)}"/><polygon points="${poly([AT,BT,CT,DT])}" fill="${shade(p.color,18)}"/><polyline points="${poly([A,B,C,D,A,AT,BT,CT,DT,AT])}" fill="none" stroke="rgba(8,32,53,.38)" stroke-width="1"/><line x1="${B.x}" y1="${B.y}" x2="${BT.x}" y2="${BT.y}" stroke="rgba(8,32,53,.38)"/><line x1="${C.x}" y1="${C.y}" x2="${CT.x}" y2="${CT.y}" stroke="rgba(8,32,53,.38)"/><line x1="${D.x}" y1="${D.y}" x2="${DT.x}" y2="${DT.y}" stroke="rgba(8,32,53,.38)"/></g>`
}
function visualizeIso(container){
  const spec=container.spec,scale=Math.min(.09,600/(spec.length+spec.width),240/spec.height),pr=(x,y,z)=>{const q=isoProject(x,y,z);return{x:q.x*scale,y:q.y*scale}},poly=a=>a.map(v=>`${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ')
  const corners=[pr(0,0,0),pr(spec.length,0,0),pr(spec.length,spec.width,0),pr(0,spec.width,0),pr(0,0,spec.height),pr(spec.length,0,spec.height),pr(spec.length,spec.width,spec.height),pr(0,spec.width,spec.height)]
  const minX=Math.min(...corners.map(p=>p.x))-36,maxX=Math.max(...corners.map(p=>p.x))+36,minY=Math.min(...corners.map(p=>p.y))-36,maxY=Math.max(...corners.map(p=>p.y))+36
  const [a,b,c,d,at,bt,ct,dt]=corners,lines=[[a,b],[b,c],[c,d],[d,a],[at,bt],[bt,ct],[ct,dt],[dt,at],[a,at],[b,bt],[c,ct],[d,dt]].map(([p,q])=>`<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"/>`).join('')
  const boxes=[...container.placements].sort((p1,p2)=>(p1.x+p1.y+p1.z)-(p2.x+p2.y+p2.z)).map(p=>isoBox(p,scale)).join('')
  return `<svg viewBox="${minX} ${minY} ${Math.max(100,maxX-minX)} ${Math.max(100,maxY-minY)}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(spec.name)} 3D 등각 적재 배치" class="load-svg"><polygon points="${poly([a,b,c,d])}" class="load-floor"/>${boxes}<g class="container-frame">${lines}</g></svg>`
}
function visualizeTop(container){
  const spec=container.spec,pad=35,vw=920,vh=360,scale=Math.min((vw-pad*2)/spec.length,(vh-pad*2)/spec.width),w=spec.length*scale,h=spec.width*scale,x=(vw-w)/2,y=(vh-h)/2
  const boxes=container.placements.map(p=>`<rect x="${x+p.x*scale}" y="${y+p.y*scale}" width="${Math.max(1,p.length*scale)}" height="${Math.max(1,p.width*scale)}" rx="2" fill="${shade(p.color,8)}" stroke="${shade(p.color,-35)}" stroke-width="1"/><text x="${x+(p.x+p.length/2)*scale}" y="${y+(p.y+p.width/2)*scale}" text-anchor="middle" dominant-baseline="middle" class="top-box-label">${esc(p.cargoName.length>8?p.cargoName.slice(0,8):p.cargoName)}</text>`).join('')
  return `<svg viewBox="0 0 ${vw} ${vh}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(spec.name)} 평면 적재 배치" class="load-svg"><defs><pattern id="grid-${container.index}" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#dfeaf2" stroke-width="1"/></pattern></defs><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#grid-${container.index})" stroke="#6689a4" stroke-width="2" rx="4"/>${boxes}<text x="${x}" y="${Math.max(18,y-10)}" class="plan-label">Door → X / ${fmtInt(spec.length)} × ${fmtInt(spec.width)} mm</text></svg>`
}
function visualizeSide(container){
  const spec=container.spec,pad=38,vw=920,vh=360,scale=Math.min((vw-pad*2)/spec.length,(vh-pad*2)/spec.height),w=spec.length*scale,h=spec.height*scale,x=(vw-w)/2,y=(vh-h)/2
  const boxes=[...container.placements].sort((a,b)=>a.z-b.z||a.x-b.x).map(p=>`<rect x="${x+p.x*scale}" y="${y+h-(p.z+p.height)*scale}" width="${Math.max(1,p.length*scale)}" height="${Math.max(1,p.height*scale)}" rx="2" fill="${shade(p.color,8)}" fill-opacity=".88" stroke="${shade(p.color,-35)}" stroke-width="1"/><text x="${x+(p.x+p.length/2)*scale}" y="${y+h-(p.z+p.height/2)*scale}" text-anchor="middle" dominant-baseline="middle" class="top-box-label">${esc(p.cargoName.length>7?p.cargoName.slice(0,7):p.cargoName)}</text>`).join('')
  return `<svg viewBox="0 0 ${vw} ${vh}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(spec.name)} 측면 적층 배치" class="load-svg"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#f8fbfd" stroke="#6689a4" stroke-width="2" rx="4"/>${boxes}<text x="${x}" y="${Math.max(18,y-10)}" class="plan-label">측면 X-Z · 적층 높이 확인 / ${fmtInt(spec.length)} × ${fmtInt(spec.height)} mm</text></svg>`
}

function visualizer(container){
  const legend=[...new Map(container.placements.map(p=>[p.cargoId,p])).values()].map(p=>`<span><i style="background:${p.color}"></i>${esc(p.cargoName)}</span>`).join('')
  return `<div class="visualizer-wrap"><div class="visualizer-toolbar"><div><strong>${esc(container.spec.shortName)} · Container ${String(container.index).padStart(2,'0')}</strong><span>내측 ${fmtInt(container.spec.length)} × ${fmtInt(container.spec.width)} × ${fmtInt(container.spec.height)} mm</span></div><div class="view-switch"><button class="${state.viewMode==='iso'?'is-active':''}" data-action="view-mode" data-id="iso">3D 등각</button><button class="${state.viewMode==='top'?'is-active':''}" data-action="view-mode" data-id="top">평면</button><button class="${state.viewMode==='side'?'is-active':''}" data-action="view-mode" data-id="side">측면 적층</button></div></div><div class="visualizer-canvas">${state.viewMode==='top'?visualizeTop(container):state.viewMode==='side'?visualizeSide(container):visualizeIso(container)}</div><div class="visualizer-legend">${legend}</div></div>`
}
function groupPlacements(container){const m=new Map();container.placements.forEach(p=>{const g=m.get(p.cargoId)||{name:p.cargoName,package:p.packagingLabel,count:0,weight:0,volume:0};g.count++;g.weight+=p.weightKg;g.volume+=boxVolumeM3(p.length,p.width,p.height);m.set(p.cargoId,g)});return [...m.values()]}

function resultsHtml(){
  const r=state.result
  if(!r)return `<section class="panel pre-result" id="results"><div class="pre-result__icon">${icon('layers',24)}</div><div><strong>아직 계산하지 않았습니다.</strong><span>포장 외형, 여유 공간, 내부 빈 공간 조건을 확인한 뒤 최적화 계산을 실행하세요.</span></div></section>`
  const totalUsable=r.containers.reduce((s,c)=>s+c.usableVolumeM3,0),totalUsed=r.containers.reduce((s,c)=>s+c.usedVolumeM3,0),totalPackedWeight=r.containers.reduce((s,c)=>s+c.usedWeightKg,0),nestedCount=r.nestedAssignments.reduce((s,a)=>s+a.placements.length,0),warnings=r.containers.reduce((s,c)=>s+c.warnings.length,0),zeroWeightTypes=state.cargo.filter(c=>packedWeightKg(c)<=0).length
  const containerRows=r.containers.map((container,idx)=>{
    const open=state.openResult===idx,grouped=groupPlacements(container),nested=container.nestedAssignments.length?`<div class="nested-list">${container.nestedAssignments.map(a=>{const gm=new Map();a.placements.forEach(p=>{const g=gm.get(p.cargoId)||{name:p.cargoName,count:0};g.count++;gm.set(p.cargoId,g)});return `<div class="nested-card"><div><strong>${esc(a.hostCargoName)}</strong><span>${esc(a.hostUid)} · ${accessLabel(a.access)}</span></div><b>${a.placements.length}개 내부 삽입</b><small>${a.usedVolumeM3.toFixed(2)} / ${a.availableVolumeM3.toFixed(2)} m³ · ${fmt(a.usedWeightKg)} kg</small><ul>${[...gm.values()].map(x=>`<li>${esc(x.name)} × ${x.count}</li>`).join('')}</ul></div>`}).join('')}</div>`:'<div class="empty-mini">이 컨테이너에서는 화물 내부 공간을 사용하지 않았습니다.</div>'
    return `<article class="container-result"><button class="container-result__head" data-action="toggle-result" data-index="${idx}" aria-expanded="${open}"><div><strong>Container ${String(container.index).padStart(2,'0')} · ${esc(container.spec.name)}</strong><span>${container.placements.length}개 외부 배치 · ${container.placements.filter(p=>p.z>container.bounds.minZ+.001).length}개 상부 적층 · 블록밀도 ${pct(container.blockDensity||0)} · ${container.layoutValidation?.valid!==false?'배치검증 통과':`검증 ${container.layoutValidation?.issues?.length||0}건`} · ${container.nestedAssignments.reduce((s,a)=>s+a.placements.length,0)}개 내부 삽입</span></div><div class="head-meters"><span>용적 <b>${pct(container.volumeUtilization)}</b></span><span>중량 <b>${pct(container.weightUtilization)}</b></span>${icon(open?'up':'down',18)}</div></button>${open?`<div class="container-result__body">${visualizer(container)}<div class="container-analytics"><div><span>무게중심 X</span><strong>${fmtInt(container.centerOfGravity.x)} mm</strong></div><div><span>무게중심 Y</span><strong>${fmtInt(container.centerOfGravity.y)} mm</strong></div><div><span>무게중심 Z</span><strong>${fmtInt(container.centerOfGravity.z)} mm</strong></div><div><span>평균 바닥하중</span><strong>${fmtInt(container.avgFloorLoadKgM2)} kg/m²</strong></div><div><span>블록 외곽 체적</span><strong>${num(container.blockEnvelopeVolumeM3).toFixed(2)} m³</strong></div><div><span>블록 내부 공극</span><strong>${num(container.blockVoidM3).toFixed(2)} m³</strong></div></div>${container.warnings.length?`<div class="container-warning">${icon('alert',18)}<div>${container.warnings.map(w=>`<span>${esc(w)}</span>`).join('')}</div></div>`:''}<div class="result-grid"><div class="result-table-wrap"><h3>외부 배치 화물</h3><table class="data-table compact"><thead><tr><th>화물</th><th>포장</th><th>수량</th><th>점유 용적</th><th>중량</th></tr></thead><tbody>${grouped.map(g=>`<tr><td>${esc(g.name)}</td><td>${esc(g.package)}</td><td>${g.count}</td><td>${g.volume.toFixed(2)} m³</td><td>${fmt(g.weight)} kg</td></tr>`).join('')}</tbody></table></div><div class="result-table-wrap"><h3>내부 빈 공간 활용</h3>${nested}</div></div><details class="placement-details"><summary>정확한 좌표 · 방향 · 포장 치수 보기</summary><div class="coordinates-grid">${container.placements.map(p=>`<div><strong>${esc(p.cargoName)}</strong><span>${esc(p.uid)} · ${esc(p.packagingLabel)}</span><code>X ${Math.round(p.x)} · Y ${Math.round(p.y)} · Z ${Math.round(p.z)}</code><small>${Math.round(p.length)} × ${Math.round(p.width)} × ${Math.round(p.height)} mm · ${esc(p.orientation)}</small></div>`).join('')}</div></details></div>`:''}</article>`
  }).join('')
  return `<section class="panel results-panel" id="results"><div class="section-head section-head--actions"><div><span class="section-number">5</span><div><h2>최적화 결과</h2><p>포장 후 외형과 작업 여유를 기준으로 컨테이너별 배치·중량·내부 공간 활용을 계산했습니다.</p></div></div><div class="button-row"><button class="button button--ghost" data-action="export-result-csv">${icon('download',16)} CSV</button><button class="button button--ghost" data-action="export-result-json">${icon('file',16)} JSON</button></div></div><div class="result-stats result-stats--six"><div class="metric">${icon('container',20)}<span>선정 컨테이너</span><strong>${r.containers.length}대</strong><small>${containerTypeSummary(r.containers.reduce((m,c)=>(m[c.spec.shortName]=(m[c.spec.shortName]||0)+1,m),{}))} · ${resultGoalLabel(r)}</small></div><div class="metric">${icon('calc',20)}<span>공간 활용률</span><strong>${pct(totalUsable?totalUsed/totalUsable:0)}</strong><small>설정 여유 제외 공간 기준</small></div><div class="metric">${icon('box',20)}<span>총 적재 중량</span><strong>${fmtInt(totalPackedWeight)} kg</strong><small>포장 자중 포함</small></div><div class="metric">${icon('package',20)}<span>포장 추가 체적</span><strong>${packagingAddedVolume().toFixed(2)} m³</strong><small>제품 실체적 대비 증가</small></div><div class="metric metric--accent">${icon('layers',20)}<span>내부 공간 활용</span><strong>${nestedCount}개</strong><small>${r.nestedSavedVolumeM3.toFixed(2)} m³ 외부 점유 절감</small></div><div class="metric ${warnings?'metric--warning':''}">${icon(warnings?'alert':'check',20)}<span>검토 경고</span><strong>${warnings}건</strong><small>무게중심·바닥하중 설정 기준</small></div></div>${r.unpacked.length?`<div class="warning-banner">${icon('alert',19)}<div><strong>${r.unpacked.length}개 화물을 현재 조건에서 적재하지 못했습니다.</strong><span>포장 외형, 문 개구부, 여유, 회전·적층 조건 또는 컨테이너 후보를 확인하세요.</span></div></div>`:''}${zeroWeightTypes?`<div class="info-banner">${icon('info',18)}<div><strong>단위중량이 0 kg인 품목이 ${zeroWeightTypes}종 있습니다.</strong><span>컨테이너 대수·공간 배치는 계산되지만 총중량, 무게중심(CG), 바닥하중은 실제 중량을 입력하기 전까지 참고용입니다.</span></div></div>`:''}${`<div class="result-assumption"><strong>현재 배치 가정</strong><span>프리셋 ${esc(state.settings.preset)} · 바닥 간격 ${fmtInt(state.settings.itemGap)} mm · 상부 간격 ${fmtInt(state.settings.stackItemGap||0)} mm · 지지율 ${Math.round(num(state.settings.supportRatio,.75)*100)}% · ${state.settings.blockContact?'블록 밀착 사용':'블록 밀착 미사용'}</span></div>`}${alternativesHtml(r)}<div class="container-results">${containerRows||'<div class="empty-state">적재 가능한 컨테이너 결과가 없습니다.</div>'}</div><div class="calc-note">계산 시간 ${r.elapsedMs.toFixed(0)} ms · 직육면체 축정렬 휴리스틱입니다. 결과는 계획/견적용 계산 보조이며 실제 선적 전에는 라싱·고정재 강도·바닥 점하중·반입 회전 경로·법규/선사 조건을 별도 확인하세요.</div></section>`
}

function exportsHtml(){if(!state.result)return'';return `<section class="panel export-panel" id="exports"><div class="section-head"><span class="section-number">6</span><div><h2>결과 내보내기</h2><p>완료된 계산을 보고서·표·이미지·원본 데이터로 저장합니다.</p></div></div><div class="export-grid"><button class="export-card export-card--pdf" data-action="export-pdf">${icon('file',24)}<div><strong>PDF 보고서</strong><span>A4 형식 · 컨테이너별 페이지</span></div></button><button class="export-card export-card--xls" data-action="export-xlsx">${icon('sheet',24)}<div><strong>Excel (XLSX)</strong><span>요약·화물·좌표·내부 적재 시트</span></div></button><button class="export-card export-card--png" data-action="export-png">${icon('image',24)}<div><strong>이미지 (PNG)</strong><span>결과 요약 + 배치 이미지</span></div></button><button class="export-card" data-action="export-result-csv">${icon('download',24)}<div><strong>CSV 좌표</strong><span>컨테이너·화물별 X/Y/Z 데이터</span></div></button><button class="export-card" data-action="export-result-json">${icon('file',24)}<div><strong>전체 JSON</strong><span>계산 조건과 결과 원본</span></div></button></div></section>`}

function modalHtml(){
  if(!state.modal)return''
  if(state.modal.type==='cargo'){
    const base=state.modal.item||normalizeCargoItem({id:`cargo-${Date.now()}`,name:'',length:1000,width:800,height:900,weightKg:100,quantity:1,rotation:'locked',orientationRules:{rotate90:false,layWidth:false,layLength:false},canBeStacked:false,canSupportCargo:false,stackable:false,maxStackLayers:1,sameCargoStackOnly:true,canBeNested:false,color:'#2f80ed',packaging:{type:state.modal.packageType||'bare'},innerSpace:{enabled:false,length:0,width:0,height:0,access:'top'}})
    const c=normalizeCargoItem(base),p=normalizePackaging(c.packaging),d=packedDimensions(c)
    return `<div class="modal-backdrop"><form class="modal modal--cargo" data-form="cargo" novalidate><header class="modal__header"><div><h2>${state.modal.item?'화물/포장 수정':'화물/포장 추가'}</h2><p>제품 실치수와 실제 출하 포장 외형을 분리해 입력합니다. 계산에는 최종 포장 외형이 사용됩니다.</p></div><button type="button" class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close',20)}</button></header><div class="modal__body"><input type="hidden" name="id" value="${esc(c.id)}"><section class="form-section"><h3>1. 제품·장비 기본 정보</h3><div class="form-grid"><label class="field field--wide"><span>화물명</span><input required name="name" value="${esc(c.name)}" placeholder="예: 제어반 / 산업용 탱크"></label>${[['length','제품 L (mm)',c.length],['width','제품 W (mm)',c.width],['height','제품 H (mm)',c.height],['weightKg','제품 단위중량 (kg)',c.weightKg],['quantity','포장 단위 수량',c.quantity]].map(([n,l,v])=>`<label class="field"><span>${l}</span><input required type="number" min="${n==='weightKg'?0:1}" step="${n==='weightKg'?'0.1':'1'}" name="${n}" value="${v}"></label>`).join('')}<div class="field field--wide orientation-rule-panel"><span>배치 허용 조건</span><small class="field-help">현장에서 판단해야 하는 것은 두 가지입니다. 어떤 자세까지 허용하는지, 적층에서 어떤 역할까지 가능한지만 정하면 계산기가 나머지 방향·배치를 자동 탐색합니다.</small><div class="rule-select-grid"><label class="field"><span>회전 조건</span><select name="orientationMode"><option value="fixed" ${orientationMode(c)==='fixed'?'selected':''}>기본 자세 고정</option><option value="upright" ${orientationMode(c)==='upright'?'selected':''}>수직 유지 · 90° 회전</option><option value="all" ${orientationMode(c)==='all'?'selected':''}>3축 회전 · 눕힘 허용</option></select><small>3축 회전은 L/W/H 축을 바꾼 최대 6가지 자세를 자동 비교합니다.</small></label><label class="field"><span>적층 조건</span><select name="stackRole"><option value="none" ${stackRole(c)==='none'?'selected':''}>적층 불가</option><option value="upper" ${stackRole(c)==='upper'?'selected':''}>상부 적재 가능</option><option value="support" ${stackRole(c)==='support'?'selected':''}>하중 지지 가능</option><option value="both" ${stackRole(c)==='both'?'selected':''}>상·하 적층 가능</option></select><small>상부에 올라가는 화물과 하중을 받는 화물을 구분합니다.</small></label></div><div class="orientation-safety-note">${icon('alert',16)} 장비를 눕힐 수 없다면 ‘수직 유지 · 90° 회전’까지만 허용하세요. 구조적으로 하중을 받을 수 없는 장비는 ‘하중 지지 가능’으로 설정하지 마세요.</div></div></div></section><section class="form-section form-section--accent"><div class="form-section__head"><div><h3>2. 포장 방식</h3><p>우드 고정, 스키드, 크레이트, 팔레트, 철제 프레임 등을 최종 점유 외형에 반영합니다.</p></div><span class="computed-badge" id="packed-preview">최종 ${fmtInt(d.length)} × ${fmtInt(d.width)} × ${fmtInt(d.height)} mm · ${fmt(packedWeightKg(c))} kg</span></div><div class="form-grid"><label class="field field--wide"><span>포장 방식</span><select name="packagingType" id="packaging-type">${Object.entries(packagingPresets).map(([id,x])=>`<option value="${id}" ${p.type===id?'selected':''}>${esc(x.label)}</option>`).join('')}</select><small>아래 기본값은 시작값이며 실제 제작 도면/포장업체 치수에 맞게 수정하세요.</small></label><label class="field"><span>전체 L 추가 (mm)</span><input data-pack-field type="number" min="0" name="packAddLength" value="${num(p.addLength)}"></label><label class="field"><span>전체 W 추가 (mm)</span><input data-pack-field type="number" min="0" name="packAddWidth" value="${num(p.addWidth)}"></label><label class="field"><span>전체 H 추가 (mm)</span><input data-pack-field type="number" min="0" name="packAddHeight" value="${num(p.addHeight)}"></label><label class="field"><span>포장 자중 (kg)</span><input data-pack-field type="number" min="0" step="0.1" name="packTareWeight" value="${num(p.tareWeightKg)}"></label><label class="field field--wide"><span>포장/고정 메모</span><input name="packMemo" value="${esc(p.memo||'')}" placeholder="예: 100×100 각재 베이스, 전후 스토퍼, 방습필름"></label><div class="field field--wide field-row"><label class="check"><input id="override-outer" type="checkbox" name="overrideOuter" ${p.overrideOuter?'checked':''}><span>실제 완성 포장 외형을 직접 입력</span></label></div><div class="override-grid ${p.overrideOuter?'':'is-hidden'}" id="override-grid"><label class="field"><span>완성 포장 L (mm)</span><input data-pack-field type="number" min="1" name="outerLength" value="${num(p.outerLength,d.length)}" ${p.overrideOuter?'required':'disabled'}></label><label class="field"><span>완성 포장 W (mm)</span><input data-pack-field type="number" min="1" name="outerWidth" value="${num(p.outerWidth,d.width)}" ${p.overrideOuter?'required':'disabled'}></label><label class="field"><span>완성 포장 H (mm)</span><input data-pack-field type="number" min="1" name="outerHeight" value="${num(p.outerHeight,d.height)}" ${p.overrideOuter?'required':'disabled'}></label></div></div></section><section class="form-section"><h3>3. 적층 세부조건·내부 공간</h3><div class="stack-rule-grid"><div class="stack-info-card"><strong>${stackRoleLabel(stackRole(c))}</strong><small>위에서 선택한 적층 역할이 기준입니다. 여기서는 최대 단수와 동일 품목 제한만 추가로 설정합니다.</small></div><label class="field"><span>최대 적층 단수</span><input type="number" min="1" max="10" name="maxStackLayers" value="${Math.max(2,c.maxStackLayers||2)}"><small>일반적인 2단 적층이면 2. 구조적으로 가능한 범위만 입력하세요.</small></label><label class="check stack-check"><input type="checkbox" name="sameCargoStackOnly" ${c.sameCargoStackOnly?'checked':''}><span><strong>동일 품목끼리만 적층</strong><small>해제하면 다른 적층 허용 제품과도 블록 조합</small></span></label><label class="check stack-check"><input type="checkbox" name="canBeNested" ${c.canBeNested?'checked':''}><span><strong>다른 화물 내부에 삽입 가능</strong><small>탱크·프레임 내부 활용 대상</small></span></label><label class="color-field"><span>구분색</span><input type="color" name="color" value="${esc(c.color)}"></label></div><div class="stack-safety-note">${icon('layers',16)} <span><b>블록 적층 로직:</b> 적층 가능 품목으로 하부 지지면을 먼저 만들고, 그 위의 연속된 빈 공간을 다시 하나의 적재층처럼 탐색합니다. 품목 경계에 걸쳐 올라가도 설정한 지지율을 만족하면 후보로 사용합니다.</span></div><div class="inner-space"><div class="inner-space__head"><div><strong>제품/장비 내부 사용가능 공간</strong><p>상부 개방 탱크·프레임처럼 실제로 작은 화물을 넣어 함께 포장할 수 있을 때만 켜세요.</p></div><label class="switch"><input type="checkbox" name="innerEnabled" ${c.innerSpace?.enabled?'checked':''}><span></span></label></div><div class="inner-space__grid"><label class="field"><span>내측 L (mm)</span><input type="number" min="0" name="innerLength" value="${c.innerSpace?.length||0}"></label><label class="field"><span>내측 W (mm)</span><input type="number" min="0" name="innerWidth" value="${c.innerSpace?.width||0}"></label><label class="field"><span>내측 H (mm)</span><input type="number" min="0" name="innerHeight" value="${c.innerSpace?.height||0}"></label><label class="field"><span>접근 방향</span><select name="innerAccess"><option value="top" ${c.innerSpace?.access==='top'?'selected':''}>상부 개방</option><option value="side" ${c.innerSpace?.access==='side'?'selected':''}>측면 개방</option><option value="full" ${c.innerSpace?.access==='full'?'selected':''}>완전 개방</option></select></label><label class="field"><span>내부 허용 중량 (kg)</span><input type="number" min="0" name="innerMaxPayload" value="${c.innerSpace?.maxPayloadKg||''}" placeholder="0 = 제한 미설정"></label></div></div></section></div><footer class="modal__footer"><button type="button" class="button button--ghost" data-action="close-modal">취소</button><button class="button button--primary" type="submit">화물 저장</button></footer></form></div>`
  }
  const c=state.modal.item||{id:`custom-${Date.now()}`,name:'사용자 컨테이너',shortName:'CUSTOM',length:6000,width:2350,height:2400,doorWidth:2300,doorHeight:2280,maxPayloadKg:25000,nominalVolumeM3:33.8,enabled:true,custom:true}
  return `<div class="modal-backdrop"><form class="modal modal--small" data-form="container" novalidate><header class="modal__header"><div><h2>${state.modal.item?'컨테이너 규격 수정':'사용자 컨테이너 추가'}</h2><p>실제 계산에는 반드시 내측 사용 가능 치수를 입력하세요.</p></div><button type="button" class="icon-button" data-action="close-modal">${icon('close',20)}</button></header><div class="modal__body form-grid"><input type="hidden" name="id" value="${esc(c.id)}"><label class="field field--wide"><span>규격명</span><input required name="name" value="${esc(c.name)}"></label>${[['length','내측 L (mm)',c.length],['width','내측 W (mm)',c.width],['height','내측 H (mm)',c.height],['doorWidth','문 개구 폭 (mm)',c.doorWidth||''],['doorHeight','문 개구 높이 (mm)',c.doorHeight||''],['maxPayloadKg','최대 적재중량 (kg)',c.maxPayloadKg]].map(([n,l,v])=>`<label class="field"><span>${l}</span><input ${n==='maxPayloadKg'||['length','width','height'].includes(n)?'required':''} type="number" min="0" name="${n}" value="${v}"></label>`).join('')}</div><footer class="modal__footer"><button type="button" class="button button--ghost" data-action="close-modal">취소</button><button class="button button--primary" type="submit">규격 저장</button></footer></form></div>`
}

function render(){
  const keepScroll=window.scrollY
  const usable=state.containers.filter(c=>c.enabled).length
  document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar ${state.mobileNav?'is-open':''}"><div class="brand"><div class="brand-mark">${icon('container',25)}</div><div><strong>Container Fit</strong><span>실무 적재 최적화</span></div><button class="sidebar-close" data-action="mobile-close">${icon('close',22)}</button></div><nav class="side-nav" aria-label="주요 메뉴"><button data-scroll="dashboard">${icon('calc')}<span>개요</span></button><button data-scroll="containers">${icon('container')}<span>컨테이너</span></button><button data-scroll="cargo">${icon('box')}<span>화물 목록</span></button><button data-scroll="packaging">${icon('package')}<span>포장 사양</span></button><button data-scroll="settings">${icon('ruler')}<span>적재 조건</span></button><button data-scroll="results">${icon('layers')}<span>배치 결과</span></button><button data-scroll="exports" ${state.result?'':'disabled'}>${icon('download')}<span>내보내기</span></button></nav><div class="sidebar-guide">${icon('info',19)}<strong>계산 기준</strong><ol><li>내측 규격·문 개구 반영</li><li>포장 외형·회전·적층 반영</li><li>빈 공간·중량·여유 검토</li></ol></div><div class="sidebar-actions"><button class="sidebar-new-project" data-action="new-project">${icon('plus',16)}새 프로젝트</button><button data-action="export-project">${icon('save',16)}프로젝트 저장</button><button data-action="open-project-file">${icon('upload',16)}불러오기</button></div></aside><div class="main-column"><header class="topbar"><button class="mobile-menu" data-action="mobile-open">${icon('menu',22)}</button><div><strong>컨테이너 포장 최적화</strong><span>포장 후 외형과 내측 빈 공간을 함께 계산하는 적재 시뮬레이터</span></div><div class="topbar-actions"><button class="button button--ghost" data-action="new-project">${icon('plus',16)} 새 프로젝트</button><button class="button button--ghost" data-action="export-project">${icon('download',16)} 프로젝트</button></div></header><main class="workspace"><section class="intro-panel" id="dashboard"><div><h1>제품 실치수부터 우드 고정·크레이트까지, 실제 출하 외형으로 계산합니다.</h1><p>제품/장비 외형과 포장 후 점유 외형을 분리하고, 탱크·프레임 내부의 실제 적재 가능 공간까지 재사용하여 컨테이너 종류·수량·배치를 계산합니다.</p></div><div class="intro-summary"><div><span>포장 단위</span><strong>${unitCount()}개</strong></div><div><span>포장 후 체적</span><strong>${totalPackedVolume().toFixed(2)} m³</strong></div><div><span>총 출하중량</span><strong>${fmtInt(totalWeight())} kg</strong></div><div><span>포장 증가 체적</span><strong>+${packagingAddedVolume().toFixed(2)} m³</strong></div></div></section><div class="steps">${[['1','컨테이너 선택','내측·문 규격'],['2','화물 등록','제품 실치수'],['3','포장 방식','우드·크레이트·팔레트'],['4','여유 공간','작업·벽·통로'],['5','최적화 계산','배치·중량·CG'],['6','결과 저장','PDF·Excel·PNG']].map(([n,t,d])=>`<div class="step"><span>${n}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div><section class="panel" id="containers"><div class="section-head section-head--actions"><div><span class="section-number">1</span><div><h2>컨테이너 내측 규격</h2><p>후보로 사용할 규격만 선택하세요. 사용자 규격도 추가할 수 있습니다.</p></div></div><button class="button button--soft" data-action="add-container">${icon('plus',16)} 규격 추가</button></div><div class="container-cards">${containerCards()}</div></section><section class="panel" id="cargo"><div class="section-head section-head--actions"><div><span class="section-number">2</span><div><h2>화물·포장 사양</h2><p>제품 실치수, 포장 외형, 수량과 적재 조건을 한 화면에서 관리합니다. <b>CSV 저장</b>은 현재 목록과 설정을 그대로 내보냅니다.</p></div></div><div class="button-row cargo-actions"><button class="button button--ghost" data-action="export-cargo-csv">${icon('download',16)} CSV 저장</button><button class="button button--ghost" data-action="open-csv-file">${icon('upload',16)} CSV 불러오기</button><button class="button button--soft" data-action="load-example">${icon('spark',16)} 예제 불러오기</button><button class="button button--ghost" data-action="clear-cargo" ${state.cargo.length?'':'disabled'}>${icon('trash',16)} 목록 비우기</button><button class="button button--primary" data-action="add-cargo">${icon('plus',16)} 화물 추가</button></div></div><div class="table-scroll"><table class="data-table cargo-table"><colgroup><col class="c-name"><col class="c-pack"><col class="c-qty"><col class="c-rule"><col class="c-inner"><col class="c-actions"></colgroup><thead><tr><th>화물 / 제품 규격</th><th>포장 외형</th><th>수량</th><th>적재 조건</th><th>내부 활용</th><th class="align-right">관리</th></tr></thead><tbody>${cargoRows()}</tbody></table></div>${state.cargo.length?`<div class="orientation-tip">${icon('info',16)}<span><b>블록 적재:</b> ‘3축 회전’은 허용된 자세를 자동 비교하고, ‘하중 지지 가능’ 화물의 상부면을 지지 영역으로 구성해 ‘상부 적재 가능’ 화물을 우선 배치합니다.</span></div>`:`<div class="empty-state empty-state--actions"><strong>화물 목록이 비어 있습니다.</strong><span>직접 등록하거나 CSV를 불러오세요. 기능을 먼저 확인하려면 예제 데이터를 사용할 수 있습니다.</span><div class="button-row"><button class="button button--soft" data-action="load-example">${icon('spark',16)} 예제 데이터</button><button class="button button--primary" data-action="add-cargo">${icon('plus',16)} 첫 화물 추가</button></div></div>`}</section><section class="panel" id="packaging"><div class="section-head"><span class="section-number">3</span><div><h2>포장 사양</h2><p>장비 직접 적재뿐 아니라 우드 블로킹, 스키드, 크레이트, 팔레트, 철제 프레임 등 실제 점유 공간을 계산합니다.</p></div></div><div class="package-library">${packagingCards()}</div><div class="logic-note">${icon('spark',18)}<div><strong>실무 적용 방식</strong><span>각 포장 방식의 추가 치수·자중은 편집 가능한 시작값입니다. 실제 포장 도면이 있으면 “완성 포장 외형 직접 입력”을 사용하여 그 치수를 최우선으로 계산하세요.</span></div></div></section><section class="panel" id="settings"><div class="section-head"><span class="section-number">4</span><div><h2>적재 조건</h2><p>최적화 목표, 작업 여유, 반입 한계, 품목 간 간격과 적층 지지조건을 설정합니다.</p></div></div><div class="optimization-block"><div class="subsection-title"><strong>최적화 목표</strong><span>기본은 블록화·적층을 먼저 활용하고 대수와 잔량을 줄입니다. 특정 컨테이너 선호가 있으면 별도로 선택하세요.</span></div><div class="preset-grid optimization-grid">${optimizationCards()}</div></div><div class="subsection-title subsection-title--border"><strong>작업 여유 프리셋</strong><span>최대 밀도 / 실무 기본 / 안전 여유를 선택한 뒤 세부값을 조정할 수 있습니다.</span></div><div class="preset-grid">${presetCards()}</div><div class="settings-grid settings-grid--dense">${[['itemGap','바닥 화물 간 최소 간격','컨테이너 바닥에 놓이는 포장 단위 간 간격','mm',0,300],['stackItemGap','상부 적층 화물 간 간격','상부 블록/2단 화물끼리의 수평 간격','mm',0,300],['verticalGap','수직 적층 간격','받침재/완충재로 생기는 높이 간격','mm',0,300],['doorClearance','문측 작업 여유','문에서 컨테이너 안쪽으로 비워둘 길이','mm',0,1000],['rearClearance','후면 여유','컨테이너 안쪽 끝벽 여유','mm',0,500],['sideClearance','좌우 벽면 여유','양 측벽에서 각각 제외','mm',0,500],['ceilingClearance','천장 여유','최상단 적재 제한','mm',0,500],['floorClearance','바닥 받침 높이','전체 화물 하부에 공통 확보할 높이','mm',0,300],['aisleWidth','측면 통로 폭','작업/점검 통로를 한쪽에 예약','mm',0,1000],['doorPassClearance','문 개구 통과 여유','문 폭·높이에서 추가로 제외','mm',0,200],['maxLoadHeight','최대 적재 높이','0이면 컨테이너 내측 높이 사용','mm',0,4000],['maxFloorLoadKgM2','평균 바닥하중 경고값','0이면 경고 검사 안 함','kg/m²',0,20000]].map(([k,t,d,u,min,max])=>`<label class="setting-control"><div><strong>${t}</strong><span>${d}</span></div><div class="number-unit"><input data-setting="${k}" type="number" min="${min}" max="${max}" value="${num(state.settings[k])}"><span>${u}</span></div></label>`).join('')}<label class="setting-control"><div><strong>상부 적재 지지율</strong><span>아래 화물이 지지해야 하는 바닥 면적 비율</span></div><div class="number-unit"><input data-setting="supportRatioPct" type="number" min="50" max="100" value="${Math.round(num(state.settings.supportRatio,.75)*100)}"><span>%</span></div></label><label class="setting-toggle"><div><strong>화물 내부 빈 공간 활용</strong><span>탱크·프레임 안에 작은 화물을 먼저 배치</span></div><label class="switch"><input data-setting="useInnerSpaces" type="checkbox" ${state.settings.useInnerSpaces?'checked':''}><span></span></label></label><label class="setting-toggle"><div><strong>블록 맞댐 배치</strong><span>적층 가능 품목끼리는 설정 간격 대신 맞대어 하나의 블록처럼 배치</span></div><label class="switch"><input data-setting="blockContact" type="checkbox" ${state.settings.blockContact?'checked':''}><span></span></label></label></div><div class="logic-note">${icon('spark',18)}<div><strong>블록/내부 공간 활용 로직</strong><span>적층 가능 품목은 하부 지지면과 상부 층을 따로 계산하고, 탱크·프레임의 내측 L×W×H는 별도 미니 적재공간으로 계산합니다. 허용하지 않은 방향 변경·적층은 사용하지 않습니다. ‘블록 맞댐 배치’를 켠 경우에만 적층 가능 품목의 수평 간격을 0으로 계산합니다.</span></div></div></section>${inputDiagnosticsHtml()}<section class="calculate-bar"><div><strong>현재 계산 대상</strong><span>${unitCount()}개 포장 단위 · 제품 ${totalRawVolume().toFixed(2)} m³ → 포장 ${totalPackedVolume().toFixed(2)} m³ · ${usable}종 컨테이너 후보</span></div><div class="calc-actions">${state.calculating?`<button class="button button--ghost" data-action="cancel-calc">계산 취소</button>`:''}<button class="button button--calculate" data-action="calculate" ${state.calculating?'disabled':''}>${icon('calc',20)} ${state.calculating?'최적화 계산 중…':state.settings.optimizationGoal==='auto'?'적재 최적화 계산':`${optimizationLabel(state.settings.optimizationGoal)} 계산`}</button></div></section>${state.calculating?`<div class="calc-progress"><span class="calc-spinner"></span><div><strong>배치 후보를 계산하고 있습니다.</strong><span>${esc(state.calcMessage||'회전·적층·컨테이너 조합을 탐색 중입니다. 화면은 계속 사용할 수 있습니다.')}</span></div></div>`:''}${resultsHtml()}${exportsHtml()}<section class="method-panel">${icon('info',20)}<div><strong>계산 모델 범위</strong><p>제품/포장 외형, 포장 자중, 내측 규격, 문 개구부, 여유 공간, 회전, 적층, 내부 빈 공간, 최대 적재중량을 반영합니다. 무게중심과 평균 바닥하중은 검토용 지표로 제공합니다. 실제 선적 시에는 고정재 강도, 라싱 포인트, 집중하중, 크레인/포크 작업성, 선사·법규 조건을 별도 확인해야 합니다.</p></div></section></main><footer class="footer"><span>Container Fit · 모든 프로젝트 데이터는 이 브라우저에 저장됩니다.</span><span>GitHub Pages 정적 환경에서 서버 없이 동작합니다.</span></footer></div>${modalHtml()}</div><input id="project-file" hidden type="file" accept="application/json,.json"><input id="csv-file" hidden type="file" accept=".csv,text/csv">`
  requestAnimationFrame(()=>{window.scrollTo(0,keepScroll);initNavigation();bindModalPackagingPreview()})
}

function setActiveNav(id){$$('.side-nav button').forEach(b=>b.classList.toggle('is-active',b.dataset.scroll===id))}
let navObserver=null
function initNavigation(){
  navObserver?.disconnect();const targets=['dashboard','containers','cargo','packaging','settings','results','exports'].map(id=>document.getElementById(id)).filter(Boolean)
  navObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)setActiveNav(visible.target.id)},{rootMargin:'-90px 0px -55% 0px',threshold:[0,.15,.4,.8]});targets.forEach(t=>navObserver.observe(t));if(!$('.side-nav .is-active'))setActiveNav('dashboard')
}
function scrollToSection(id){const el=document.getElementById(id);if(!el)return;el.scrollIntoView({behavior:'smooth',block:'start'});state.mobileNav=false;$('.sidebar')?.classList.remove('is-open');setActiveNav(id)}

function bindModalPackagingPreview(){
  const form=$('form[data-form="cargo"]');if(!form)return
  const type=$('#packaging-type',form),override=$('#override-outer',form),grid=$('#override-grid',form)
  const update=()=>{
    grid?.classList.toggle('is-hidden',!override?.checked)
    ;['outerLength','outerWidth','outerHeight'].forEach(n=>{const el=form.elements[n];if(el){el.disabled=!override?.checked;el.required=Boolean(override?.checked)}})
    const fd=new FormData(form),p={type:fd.get('packagingType'),addLength:num(fd.get('packAddLength')),addWidth:num(fd.get('packAddWidth')),addHeight:num(fd.get('packAddHeight')),tareWeightKg:num(fd.get('packTareWeight')),overrideOuter:fd.has('overrideOuter'),outerLength:num(fd.get('outerLength')),outerWidth:num(fd.get('outerWidth')),outerHeight:num(fd.get('outerHeight'))},tmp={length:num(fd.get('length')),width:num(fd.get('width')),height:num(fd.get('height')),weightKg:num(fd.get('weightKg')),packaging:p},d=packedDimensions(tmp);const out=$('#packed-preview',form);if(out)out.textContent=`최종 ${fmtInt(d.length)} × ${fmtInt(d.width)} × ${fmtInt(d.height)} mm · ${fmt(packedWeightKg(tmp))} kg`
  }
  type?.addEventListener('change',()=>{const p=packagePreset(type.value);[['packAddLength',p.addLength],['packAddWidth',p.addWidth],['packAddHeight',p.addHeight],['packTareWeight',p.tareWeightKg]].forEach(([n,v])=>{const el=form.elements[n];if(el)el.value=v});update()})
  form.addEventListener('input',update);form.addEventListener('change',update);update()
}

function exportTimestamp(d=new Date()){const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}_${pad(d.getHours())}-${pad(d.getMinutes())}-${pad(d.getSeconds())}`}
function timestampedFilename(filename){const dot=filename.lastIndexOf('.');return dot>0?`${filename.slice(0,dot)}_${exportTimestamp()}${filename.slice(dot)}`:`${filename}_${exportTimestamp()}`}
function downloadBlob(filename,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=timestampedFilename(filename);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1200)}
function downloadText(filename,text,type='application/json;charset=utf-8'){downloadBlob(filename,new Blob([text],{type}))}
const csvEscape=v=>/[",\n]/.test(String(v))?`"${String(v).replaceAll('"','""')}"`:String(v)
function exportProject(){downloadText('container-fit-project.json',JSON.stringify({version:9,containers:state.containers,cargo:state.cargo,settings:state.settings},null,2));toast('프로젝트 JSON을 저장했습니다. 파일명에 저장 일시가 포함됩니다.','success')}
function exportResultJson(){if(!state.result)return;downloadText('container-fit-result.json',JSON.stringify({generatedAt:new Date().toISOString(),settings:state.settings,cargo:state.cargo,requestedGoal:state.result.requestedGoal||state.settings.optimizationGoal,selectedStrategy:state.result.selectedStrategy||state.result.goal,alternatives:state.result.alternatives||[],containers:state.result.containers,unpacked:state.result.unpacked},null,2));toast('전체 결과 JSON을 저장했습니다.','success')}
function placementRows(){const rows=[['containerNo','containerType','cargo','packaging','unitId','x_mm','y_mm','z_mm','length_mm','width_mm','height_mm','weight_kg','orientation','nestedInside']];state.result?.containers.forEach(c=>{c.placements.forEach(p=>rows.push([c.index,c.spec.name,p.cargoName,p.packagingLabel,p.uid,p.x,p.y,p.z,p.length,p.width,p.height,p.weightKg,p.orientation,'']));c.nestedAssignments.forEach(a=>a.placements.forEach(p=>rows.push([c.index,c.spec.name,p.cargoName,p.packagingLabel,p.uid,p.x,p.y,p.z,p.length,p.width,p.height,p.weightKg,p.orientation,a.hostUid]))) });return rows}
function exportResultCsv(){if(!state.result)return;downloadText('container-fit-placement.csv','\uFEFF'+placementRows().map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv;charset=utf-8');toast('배치 좌표 CSV를 저장했습니다. 파일명에 저장 일시가 포함됩니다.','success')}
const cargoCsvHeaders=['name','length','width','height','weightKg','quantity','packagingType','packAddLength','packAddWidth','packAddHeight','packTareWeight','packMemo','overrideOuter','outerLength','outerWidth','outerHeight','orientationMode','stackRole','maxStackLayers','sameCargoStackOnly','canBeNested','color','innerEnabled','innerLength','innerWidth','innerHeight','innerAccess','innerMaxPayload']
function cargoCsvRow(c){const p=normalizePackaging(c.packaging),i=c.innerSpace||{};return [c.name,c.length,c.width,c.height,c.weightKg,c.quantity,p.type||'bare',num(p.addLength),num(p.addWidth),num(p.addHeight),num(p.tareWeightKg),p.memo||'',Boolean(p.overrideOuter),p.overrideOuter?num(p.outerLength):'',p.overrideOuter?num(p.outerWidth):'',p.overrideOuter?num(p.outerHeight):'',orientationMode(c),stackRole(c),Math.max(1,Math.floor(num(c.maxStackLayers,1))),Boolean(c.sameCargoStackOnly),Boolean(c.canBeNested),c.color||'',Boolean(i.enabled),i.enabled?num(i.length):'',i.enabled?num(i.width):'',i.enabled?num(i.height):'',i.enabled?(i.access||'top'):'',i.enabled?num(i.maxPayloadKg):'']}
function cargoCsvText(rows=state.cargo){return '\uFEFF'+[cargoCsvHeaders,...rows.map(cargoCsvRow)].map(r=>r.map(csvEscape).join(',')).join('\n')}
function exportCargoCsv(){if(!state.cargo.length)return toast('저장할 화물 목록이 없습니다.','error');downloadText('container-fit-cargo.csv',cargoCsvText(),'text/csv;charset=utf-8');toast(`현재 화면의 화물 ${state.cargo.length}종을 CSV로 저장했습니다.`, 'success')}
function csvTemplate(){downloadText('container-fit-cargo-template-v8.csv','\uFEFF'+cargoCsvHeaders.map(csvEscape).join(','),'text/csv;charset=utf-8');toast('새 입력용 빈 CSV 양식을 저장했습니다. 현재 목록을 저장하려면 “CSV 저장”을 사용하세요.','success')}

function parseSimpleCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);const parseLine=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(ch===','&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out};const headers=parseLine(lines[0]).map(x=>x.trim());return lines.slice(1).map(line=>{const values=parseLine(line);return Object.fromEntries(headers.map((h,i)=>[h,(values[i]||'').trim()]))})}
async function importProject(file){try{if(state.calculating)invalidateActiveCalculation();const p=JSON.parse(await file.text());if(!Array.isArray(p.containers)||!Array.isArray(p.cargo)||!p.settings)throw 0;state.containers=p.containers;state.cargo=p.cargo.map(x=>normalizeCargoItem(x,{resetLegacyOrientation:num(p.version)<4}));state.settings=normalizeSettings(p.settings);state.result=null;persist();render();toast('프로젝트를 불러왔습니다.','success')}catch{toast('올바른 Container Fit 프로젝트 JSON이 아닙니다.','error')}}
async function importCsv(file){try{if(state.calculating)invalidateActiveCalculation();
  const rows=parseSimpleCsv(await file.text());if(!rows.length)throw 0
  const needed=['name','length','width','height','weightKg','quantity'];if(needed.some(k=>!(k in rows[0])))throw 0
  const parsed=rows.map((r,i)=>{
    const type=packagingPresets[r.packagingType]?r.packagingType:'bare',preset=packagePreset(type)
    const hasQuickOrientation=['allowRotate','allowLay'].some(k=>k in r),hasNewOrientation=['rotate90','layWidth','layLength'].some(k=>k in r)
    const quickLay=r.allowLay==='true'
    const oldRules=(hasQuickOrientation||hasNewOrientation)?{rotate90:r.allowRotate==='true'||r.rotate90==='true',layWidth:quickLay||r.layWidth==='true',layLength:quickLay||r.layLength==='true'}:{rotate90:false,layWidth:false,layLength:false}
    const mode=['fixed','upright','all'].includes(r.orientationMode)?r.orientationMode:(r.directionChangeAllowed==='true'?'all':r.directionChangeAllowed==='false'?'fixed':null)
    const rules=mode?orientationRulesForMode(mode):oldRules
    let role=['none','upper','support','both'].includes(r.stackRole)?r.stackRole:null
    if(!role){const up=r.allowStackOn==='true'||r.canBeStacked==='true',support=r.allowSupport==='true'||r.canSupportCargo==='true'||r.stackable==='true',legacy=r.stackAllowed==='true';role=legacy?'both':up&&support?'both':up?'upper':support?'support':'none'}
    const flags=stackRoleFlags(role)
    return normalizeCargoItem({id:`csv-${Date.now()}-${i}`,name:r.name||`화물 ${i+1}`,length:num(r.length),width:num(r.width),height:num(r.height),weightKg:num(r.weightKg),quantity:num(r.quantity),rotation:'locked',orientationRules:rules,canBeStacked:flags.canBeStacked,canSupportCargo:flags.canSupportCargo,stackable:flags.canSupportCargo,maxStackLayers:Math.max(1,Math.floor(num(r.maxStackLayers,role==='none'?1:2))),sameCargoStackOnly:r.sameCargoStackOnly===''||r.sameCargoStackOnly==null?false:r.sameCargoStackOnly==='true',canBeNested:r.canBeNested==='true',color:r.color||['#2f80ed','#0f8b8d','#f2b84b','#7b61ff'][i%4],packaging:{...preset,type,addLength:r.packAddLength===''?preset.addLength:num(r.packAddLength),addWidth:r.packAddWidth===''?preset.addWidth:num(r.packAddWidth),addHeight:r.packAddHeight===''?preset.addHeight:num(r.packAddHeight),tareWeightKg:r.packTareWeight===''?preset.tareWeightKg:num(r.packTareWeight),memo:r.packMemo||'',overrideOuter:r.overrideOuter==='true'||Boolean(num(r.outerLength)&&num(r.outerWidth)&&num(r.outerHeight)),outerLength:num(r.outerLength),outerWidth:num(r.outerWidth),outerHeight:num(r.outerHeight)},innerSpace:{enabled:r.innerEnabled==='true'||Boolean(num(r.innerLength)&&num(r.innerWidth)&&num(r.innerHeight)),length:num(r.innerLength),width:num(r.innerWidth),height:num(r.innerHeight),access:['top','side','full'].includes(r.innerAccess)?r.innerAccess:'top',maxPayloadKg:num(r.innerMaxPayload)}})
  })
  if(parsed.some(x=>!x.name||x.length<=0||x.width<=0||x.height<=0||x.quantity<=0))throw 0
  state.cargo=parsed;state.result=null;persist();render();toast(`${parsed.length}개 화물 유형을 불러왔습니다. 적재 방향·적층 역할은 CSV에 지정된 범위만 계산에 사용됩니다.`,'success')
}catch{toast('CSV 형식을 확인하세요. 필수 헤더: name,length,width,height,weightKg,quantity','error')}}


let calcWorker=null,calcToken=0,calcTimer=null
function stopCalculation(message=''){
  calcWorker?.terminate();calcWorker=null;if(calcTimer){clearTimeout(calcTimer);calcTimer=null}
  state.calculating=false;state.calcMessage='';if(message)toast(message,'info');render()
}
function invalidateActiveCalculation(){
  if(!state.calculating)return
  calcToken++;calcWorker?.terminate();calcWorker=null;if(calcTimer){clearTimeout(calcTimer);calcTimer=null}
  state.calculating=false;state.calcMessage=''
}
function run(){
  const enabled=state.containers.filter(c=>c.enabled);if(!enabled.length)return toast('사용할 컨테이너 규격을 최소 1개 선택하세요.','error');if(!state.cargo.length||!unitCount())return toast('계산할 화물을 추가하세요.','error');if(unitCount()>1200)return toast('브라우저 계산 안정성을 위해 한 번에 1,200개 이하로 계산해 주세요.','error')
  const invalid=state.cargo.find(c=>{const d=packedDimensions(c);return c.length<=0||c.width<=0||c.height<=0||d.length<=0||d.width<=0||d.height<=0||c.quantity<=0||c.weightKg<0});if(invalid)return toast(`${invalid.name||'화물'}의 제품/포장 치수·수량·중량을 확인하세요.`,'error')
  if(state.calculating)return
  const token=++calcToken;state.calculating=true;state.calcMessage=`${unitCount()}개 포장 단위 · ${enabled.length}종 컨테이너 후보`;render()
  const payload={cargo:clone(state.cargo),containers:clone(state.containers),settings:clone(state.settings)}
  const finish=(result)=>{if(token!==calcToken)return;calcWorker?.terminate();calcWorker=null;if(calcTimer){clearTimeout(calcTimer);calcTimer=null};state.calculating=false;state.calcMessage='';state.result=result;state.openResult=0;persist();render();toast(result.unpacked.length?`계산 완료: ${result.unpacked.length}개는 현재 조건에서 적재되지 않았습니다.`:`계산 완료: ${result.containers.length}대에 전체 화물을 배치했습니다.`,result.unpacked.length?'info':'success');setTimeout(()=>scrollToSection('results'),100)}
  const fail=(message)=>{if(token!==calcToken)return;calcWorker?.terminate();calcWorker=null;if(calcTimer){clearTimeout(calcTimer);calcTimer=null};state.calculating=false;state.calcMessage='';render();toast(message||'계산 중 오류가 발생했습니다.','error')}
  try{
    if(typeof Worker==='undefined')return setTimeout(()=>{try{finish(optimizePacking(payload.cargo,payload.containers,payload.settings))}catch(e){fail(e?.message)}},30)
    calcWorker=new Worker(new URL('./packing-worker.js',import.meta.url),{type:'module'})
    calcWorker.onmessage=e=>e.data?.ok?finish(e.data.result):fail(e.data?.error||'계산 중 오류가 발생했습니다.')
    calcWorker.onerror=()=>fail('계산 모듈을 실행하지 못했습니다. 새로고침 후 다시 시도하세요.')
    calcWorker.postMessage(payload)
    calcTimer=setTimeout(()=>fail('계산 시간이 15초를 초과해 자동 중단했습니다. 품목 수나 적층 조건을 확인한 뒤 다시 계산하세요.'),15000)
  }catch(e){setTimeout(()=>{try{finish(optimizePacking(payload.cargo,payload.containers,payload.settings))}catch(err){fail(err?.message)}},30)}
}
// ---------- XLSX export (dependency-free, ZIP store method) ----------
const crcTable=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})()
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function u16(n){return new Uint8Array([n&255,(n>>>8)&255])} function u32(n){return new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255])}
function concatBytes(parts){const len=parts.reduce((s,p)=>s+p.length,0),out=new Uint8Array(len);let o=0;parts.forEach(p=>{out.set(p,o);o+=p.length});return out}
function zipStore(files){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const f of files){const name=enc.encode(f.name),data=typeof f.data==='string'?enc.encode(f.data):f.data,crc=crc32(data);const local=concatBytes([u32(0x04034b50),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);locals.push(local);const central=concatBytes([u32(0x02014b50),u16(20),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);centrals.push(central);offset+=local.length}const centralBlock=concatBytes(centrals),localBlock=concatBytes(locals),end=concatBytes([u32(0x06054b50),u16(0),u16(0),u16(files.length),u16(files.length),u32(centralBlock.length),u32(localBlock.length),u16(0)]);return new Blob([localBlock,centralBlock,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function colName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s}
function sheetXml(rows){return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="18"/><sheetData>${rows.map((row,ri)=>`<row r="${ri+1}">${row.map((v,ci)=>{const ref=`${colName(ci+1)}${ri+1}`;if(typeof v==='number'&&Number.isFinite(v))return `<c r="${ref}"><v>${v}</v></c>`;return `<c r="${ref}" t="inlineStr"><is><t>${xmlEsc(v??'')}</t></is></c>`}).join('')}</row>`).join('')}</sheetData></worksheet>`}
function exportXlsx(){
  if(!state.result)return
  const r=state.result,summary=[['Container Fit 결과 보고서'],['생성일',new Date().toLocaleString('ko-KR')],['최적화 목표',optimizationLabel(state.settings.optimizationGoal||'auto')],['실제 선택 전략',optimizationLabel(r.selectedStrategy||r.goal||state.settings.optimizationGoal||'auto')],['컨테이너 수',r.containers.length],['총 포장 단위',unitCount()],['제품 실체적(m3)',Number(totalRawVolume().toFixed(3))],['포장 후 체적(m3)',Number(totalPackedVolume().toFixed(3))],['총 출하중량(kg)',Number(totalWeight().toFixed(1))],['포장 자중(kg)',Number(r.packagingWeightKg.toFixed(1))],['내부 공간 절감(m3)',Number(r.nestedSavedVolumeM3.toFixed(3))],[],['컨테이너','규격','사용용적(m3)','활용률','중량(kg)','중량활용률','CG X(mm)','CG Y(mm)','CG Z(mm)','평균바닥하중(kg/m2)','경고']]
  r.containers.forEach(c=>summary.push([c.index,c.spec.name,Number(c.usedVolumeM3.toFixed(3)),Number((c.volumeUtilization*100).toFixed(1)),Number(c.usedWeightKg.toFixed(1)),Number((c.weightUtilization*100).toFixed(1)),Number(c.centerOfGravity.x.toFixed(0)),Number(c.centerOfGravity.y.toFixed(0)),Number(c.centerOfGravity.z.toFixed(0)),Number(c.avgFloorLoadKgM2.toFixed(0)),c.warnings.join(' / ')]))
  const cargo=[['화물명','제품 L','제품 W','제품 H','제품중량 kg','수량','포장방식','포장 L','포장 W','포장 H','출하중량 kg','허용 방향','다른 화물 위 적재','상부 지지 허용','최대 적층 단수','동일품목만','내부 L','내부 W','내부 H','내부접근']];state.cargo.forEach(c=>{const d=packedDimensions(c);cargo.push([c.name,c.length,c.width,c.height,c.weightKg,c.quantity,c.packaging.label,d.length,d.width,d.height,packedWeightKg(c),orientationSummary(c),c.canBeStacked?'Y':'N',c.canSupportCargo?'Y':'N',c.maxStackLayers,c.sameCargoStackOnly?'Y':'N',c.innerSpace.enabled?c.innerSpace.length:'',c.innerSpace.enabled?c.innerSpace.width:'',c.innerSpace.enabled?c.innerSpace.height:'',c.innerSpace.enabled?accessLabel(c.innerSpace.access):''])})
  const placement=placementRows(),nested=[['containerNo','host','hostUnitId','innerL','innerW','innerH','cargo','unitId','x','y','z','L','W','H','weightKg']];r.containers.forEach(c=>c.nestedAssignments.forEach(a=>a.placements.forEach(p=>nested.push([c.index,a.hostCargoName,a.hostUid,a.innerLength,a.innerWidth,a.innerHeight,p.cargoName,p.uid,p.x,p.y,p.z,p.length,p.width,p.height,p.weightKg]))))
  const sheets=[['Summary',summary],['Cargo',cargo],['Placement',placement],['Nested',nested],['Unpacked',[['cargo','unitId','reason'],...r.unpacked.map(u=>[u.cargoName,u.uid,u.unpackedReason||''])]]]
  const content=`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`
  const rels=`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`
  const wb=`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map(([n],i)=>`<sheet name="${xmlEsc(n)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`
  const wbr=`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`
  const styles=`<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="11"/><name val="Arial"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf xfId="0"/></cellXfs></styleSheet>`
  const files=[{name:'[Content_Types].xml',data:content},{name:'_rels/.rels',data:rels},{name:'xl/workbook.xml',data:wb},{name:'xl/_rels/workbook.xml.rels',data:wbr},{name:'xl/styles.xml',data:styles},...sheets.map(([,rows],i)=>({name:`xl/worksheets/sheet${i+1}.xml`,data:sheetXml(rows)}))]
  downloadBlob('container-fit-result.xlsx',zipStore(files));toast('Excel XLSX 결과를 저장했습니다.','success')
}

// ---------- Report canvas / PNG / PDF ----------
function roundedRect(ctx,x,y,w,h,r=12){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function text(ctx,s,x,y,size=24,weight=400,color='#17324a',align='left'){ctx.save();ctx.font=`${weight} ${size}px "Malgun Gothic","Apple SD Gothic Neo",Arial,sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='alphabetic';ctx.fillText(String(s),x,y);ctx.restore()}
function drawReportPage(container,index,total){const W=1240,H=1754,canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#0d3153';ctx.fillRect(0,0,W,154);text(ctx,'Container Fit',64,72,38,700,'#fff');text(ctx,'컨테이너 적재 최적화 결과 보고서',64,116,24,500,'#cfe5f7');text(ctx,`${index+1} / ${total}`,1170,84,20,600,'#cfe5f7','right');const r=state.result;let y=205;text(ctx,`Container ${String(container.index).padStart(2,'0')} · ${container.spec.name}`,64,y,30,700);y+=45;text(ctx,`내측 ${fmtInt(container.spec.length)} × ${fmtInt(container.spec.width)} × ${fmtInt(container.spec.height)} mm  |  문 ${fmtInt(container.spec.doorWidth||0)} × ${fmtInt(container.spec.doorHeight||0)} mm`,64,y,18,400,'#58748c');y+=50;const metrics=[['사용 용적',`${container.usedVolumeM3.toFixed(2)} m³`],['공간 활용률',pct(container.volumeUtilization)],['적재 중량',`${fmtInt(container.usedWeightKg)} kg`],['중량 활용률',pct(container.weightUtilization)],['CG X/Y/Z',`${fmtInt(container.centerOfGravity.x)} / ${fmtInt(container.centerOfGravity.y)} / ${fmtInt(container.centerOfGravity.z)} mm`],['평균 바닥하중',`${fmtInt(container.avgFloorLoadKgM2)} kg/m²`]];metrics.forEach((m,i)=>{const col=i%3,row=Math.floor(i/3),x=64+col*370,yy=y+row*112;ctx.fillStyle='#f4f8fb';roundedRect(ctx,x,yy,340,86,12);ctx.fill();text(ctx,m[0],x+20,yy+30,16,500,'#6c8498');text(ctx,m[1],x+20,yy+64,24,700,'#17324a')});y+=245;ctx.fillStyle='#f8fbfd';roundedRect(ctx,64,y,1112,440,14);ctx.fill();text(ctx,'평면 배치도 (Door → X)',88,y+42,20,700);const bx=100,by=y+82,bw=1040,bh=300,scale=Math.min(bw/container.spec.length,bh/container.spec.width),cw=container.spec.length*scale,ch=container.spec.width*scale,cx=bx+(bw-cw)/2,cy=by+(bh-ch)/2;ctx.strokeStyle='#6c8da7';ctx.lineWidth=3;ctx.strokeRect(cx,cy,cw,ch);container.placements.forEach(p=>{ctx.fillStyle=p.color||'#2f80ed';ctx.globalAlpha=.8;ctx.fillRect(cx+p.x*scale,cy+p.y*scale,Math.max(2,p.length*scale),Math.max(2,p.width*scale));ctx.globalAlpha=1;ctx.strokeStyle='#17324a';ctx.lineWidth=.8;ctx.strokeRect(cx+p.x*scale,cy+p.y*scale,Math.max(2,p.length*scale),Math.max(2,p.width*scale))});y+=475;text(ctx,'외부 배치 화물',64,y,22,700);y+=32;const grouped=groupPlacements(container);grouped.slice(0,16).forEach((g,i)=>{const yy=y+i*38;if(i%2===0){ctx.fillStyle='#f6f9fb';ctx.fillRect(64,yy-25,1112,34)}text(ctx,g.name,78,yy,16,600);text(ctx,g.package,460,yy,15,400,'#58748c');text(ctx,`${g.count}개`,760,yy,15,500);text(ctx,`${g.volume.toFixed(2)} m³`,900,yy,15,500);text(ctx,`${fmtInt(g.weight)} kg`,1158,yy,15,500,'#17324a','right')});y+=Math.min(16,grouped.length)*38+44;if(container.nestedAssignments.length){text(ctx,'내부 빈 공간 활용',64,y,22,700);y+=34;container.nestedAssignments.slice(0,6).forEach((a,i)=>{text(ctx,`${a.hostCargoName} (${a.hostUid})`,78,y+i*36,15,600);text(ctx,`${a.placements.length}개 삽입 · ${a.usedVolumeM3.toFixed(2)} m³ · ${fmtInt(a.usedWeightKg)} kg`,1158,y+i*36,15,400,'#0b8b63','right')});y+=Math.min(6,container.nestedAssignments.length)*36+20}if(container.warnings.length){ctx.fillStyle='#fff6df';roundedRect(ctx,64,Math.min(H-170,y),1112,72,10);ctx.fill();text(ctx,`검토: ${container.warnings.join(' / ')}`,84,Math.min(H-125,y+44),15,600,'#8d681e')}text(ctx,`생성: ${new Date().toLocaleString('ko-KR')} · Container Fit`,64,H-54,14,400,'#7890a2');return canvas}
function drawSummaryPage(){const W=1240,H=1754,canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#0d3153';ctx.fillRect(0,0,W,230);text(ctx,'Container Fit',64,84,42,700,'#fff');text(ctx,'컨테이너 적재 최적화 결과',64,135,28,600,'#fff');text(ctx,`제품 실치수 + 포장 외형 + 내부 빈 공간 + 작업 여유 · ${resultGoalLabel(state.result)}`,64,183,20,400,'#cfe5f7');let y=300;const r=state.result,used=r.containers.reduce((s,c)=>s+c.usedVolumeM3,0),usable=r.containers.reduce((s,c)=>s+c.usableVolumeM3,0),metrics=[['컨테이너',`${r.containers.length}대`],['포장 단위',`${unitCount()}개`],['포장 후 체적',`${totalPackedVolume().toFixed(2)} m³`],['총 출하중량',`${fmtInt(totalWeight())} kg`],['공간 활용률',pct(usable?used/usable:0)],['내부 절감',`${r.nestedSavedVolumeM3.toFixed(2)} m³`],['포장 자중',`${fmtInt(r.packagingWeightKg)} kg`],['미적재',`${r.unpacked.length}개`]];metrics.forEach((m,i)=>{const col=i%4,row=Math.floor(i/4),x=64+col*280,yy=y+row*120;ctx.fillStyle='#f4f8fb';roundedRect(ctx,x,yy,250,92,12);ctx.fill();text(ctx,m[0],x+18,yy+32,15,500,'#6b8497');text(ctx,m[1],x+18,yy+69,23,700)});y+=290;text(ctx,'포장 단위 요약',64,y,24,700);y+=44;state.cargo.slice(0,22).forEach((c,i)=>{const d=packedDimensions(c),yy=y+i*44;if(i%2===0){ctx.fillStyle='#f7fafc';ctx.fillRect(64,yy-28,1112,38)}text(ctx,c.name,76,yy,15,600);text(ctx,c.packaging.label,390,yy,14,400,'#58748c');text(ctx,`${fmtInt(d.length)}×${fmtInt(d.width)}×${fmtInt(d.height)}`,730,yy,14,500);text(ctx,`${c.quantity}개`,920,yy,14,500);text(ctx,`${fmtInt(packedWeightKg(c)*c.quantity)} kg`,1158,yy,14,500,'#17324a','right')});text(ctx,`생성: ${new Date().toLocaleString('ko-KR')} · Container Fit`,64,H-54,14,400,'#7890a2');return canvas}
async function exportPng(){if(!state.result)return;const canvases=[drawSummaryPage(),...state.result.containers.slice(0,12).map((c,i)=>drawReportPage(c,i,state.result.containers.length))];const W=1240,gap=20,H=canvases.reduce((s,c)=>s+c.height,0)+gap*(canvases.length-1);if(H>30000){toast('컨테이너 수가 많아 PNG는 요약 페이지만 저장합니다. 전체 결과는 PDF 또는 Excel을 사용하세요.','info');const b=await new Promise(res=>canvases[0].toBlob(res,'image/png'));downloadBlob('container-fit-summary.png',b);return}const out=document.createElement('canvas');out.width=W;out.height=H;const ctx=out.getContext('2d');ctx.fillStyle='#e9f0f5';ctx.fillRect(0,0,W,H);let y=0;canvases.forEach(c=>{ctx.drawImage(c,0,y);y+=c.height+gap});const blob=await new Promise(res=>out.toBlob(res,'image/png'));downloadBlob('container-fit-report.png',blob);toast('PNG 결과 이미지를 저장했습니다.','success')}
function dataUrlBytes(dataUrl){const b64=dataUrl.split(',')[1],bin=atob(b64),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
function ascii(s){return new TextEncoder().encode(s)}
function makePdf(jpegs){const parts=[ascii('%PDF-1.4\n%âãÏÓ\n')],offsets=[0];let offset=parts[0].length;const n=jpegs.length,objCount=2+n*3;const addObj=(id,bodyParts)=>{offsets[id]=offset;const header=ascii(`${id} 0 obj\n`),footer=ascii('\nendobj\n'),all=concatBytes([header,...bodyParts,footer]);parts.push(all);offset+=all.length};addObj(1,[ascii('<< /Type /Catalog /Pages 2 0 R >>')]);const kids=jpegs.map((_,i)=>`${3+i*3} 0 R`).join(' ');addObj(2,[ascii(`<< /Type /Pages /Kids [${kids}] /Count ${n} >>`)]);jpegs.forEach((img,i)=>{const page=3+i*3,image=4+i*3,content=5+i*3,w=595.28,h=841.89;addObj(page,[ascii(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 ${image} 0 R >> >> /Contents ${content} 0 R >>`)]);addObj(image,[ascii(`<< /Type /XObject /Subtype /Image /Width ${img.width} /Height ${img.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.bytes.length} >>\nstream\n`),img.bytes,ascii('\nendstream')]);const stream=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ`;addObj(content,[ascii(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)])});const xref=offset;let x=`xref\n0 ${objCount+1}\n0000000000 65535 f \n`;for(let i=1;i<=objCount;i++)x+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;const trailer=`trailer\n<< /Size ${objCount+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;parts.push(ascii(x+trailer));return new Blob(parts,{type:'application/pdf'})}
async function exportPdf(){if(!state.result)return;toast('PDF 보고서를 생성하고 있습니다.','info');await new Promise(r=>setTimeout(r,20));const canvases=[drawSummaryPage(),...state.result.containers.map((c,i)=>drawReportPage(c,i,state.result.containers.length))],jpegs=canvases.map(c=>({width:c.width,height:c.height,bytes:dataUrlBytes(c.toDataURL('image/jpeg',.9))}));downloadBlob('container-fit-report.pdf',makePdf(jpegs));toast('PDF 보고서를 저장했습니다.','success')}

// ---------- Events ----------
document.addEventListener('click',e=>{
  const btn=e.target.closest('[data-action],[data-scroll]');if(!btn)return
  if(btn.dataset.scroll){scrollToSection(btn.dataset.scroll);return}
  const action=btn.dataset.action,id=btn.dataset.id
  if(state.calculating&&['toggle-container','delete-container','delete-cargo','preset','optimization-goal','goal-and-calculate','new-project','load-example','clear-cargo'].includes(action))invalidateActiveCalculation()
  if(action==='mobile-open'){state.mobileNav=true;$('.sidebar')?.classList.add('is-open')}
  else if(action==='mobile-close'){state.mobileNav=false;$('.sidebar')?.classList.remove('is-open')}
  else if(action==='toggle-container'){state.containers=state.containers.map(c=>c.id===id?{...c,enabled:!c.enabled}:c);state.result=null;persist();render()}
  else if(action==='add-container'){state.modal={type:'container',item:null};render()}
  else if(action==='edit-container'){state.modal={type:'container',item:clone(state.containers.find(c=>c.id===id))};render()}
  else if(action==='delete-container'){state.containers=state.containers.filter(c=>c.id!==id);state.result=null;persist();render()}
  else if(action==='add-cargo'){state.modal={type:'cargo',item:null,packageType:'bare'};render()}
  else if(action==='add-cargo-with-package'){state.modal={type:'cargo',item:null,packageType:id};render()}
  else if(action==='edit-cargo'){state.modal={type:'cargo',item:clone(state.cargo.find(c=>c.id===id))};render()}
  else if(action==='delete-cargo'){state.cargo=state.cargo.filter(c=>c.id!==id);state.result=null;persist();render()}
  else if(action==='close-modal'){state.modal=null;render()}
  else if(action==='preset'){state.settings={...state.settings,preset:id,...presetSettings[id]};state.result=null;persist();render()}
  else if(action==='optimization-goal'){state.settings={...state.settings,optimizationGoal:id};state.result=null;persist();render();toast(`최적화 목표: ${optimizationLabel(id)}`,'info')}
  else if(action==='goal-and-calculate'){state.settings={...state.settings,optimizationGoal:id};persist();render();setTimeout(run,30)}
  else if(action==='calculate')run()
  else if(action==='cancel-calc'){calcToken++;stopCalculation('계산을 취소했습니다.')}
  else if(action==='new-project'){if(confirm('새 프로젝트를 시작할까요? 현재 화물 목록과 설정은 비워집니다. 필요한 경우 먼저 프로젝트를 저장하세요.')){calcToken++;calcWorker?.terminate();state.containers=clone(defaultContainers);state.cargo=[];state.settings=clone(defaultSettings);state.result=null;state.calculating=false;persist();render();toast('빈 프로젝트로 초기화했습니다.','success')}}
  else if(action==='load-example'){if(state.cargo.length&&!confirm('현재 화물 목록을 예제 데이터로 교체할까요?'))return;state.cargo=clone(sampleCargo).map(normalizeCargoItem);state.result=null;persist();render();toast('회전·적층·내부 공간 기능을 확인할 수 있는 예제 데이터를 불러왔습니다.','success')}
  else if(action==='clear-cargo'){if(state.cargo.length&&confirm('화물 목록을 모두 삭제할까요? 컨테이너 규격과 적재 조건은 유지됩니다.')){calcToken++;calcWorker?.terminate();state.cargo=[];state.result=null;state.calculating=false;persist();render();toast('화물 목록을 비웠습니다.','success')}}
  else if(action==='export-project')exportProject()
  else if(action==='open-project-file')$('#project-file')?.click()
  else if(action==='open-csv-file')$('#csv-file')?.click()
  else if(action==='export-cargo-csv')exportCargoCsv()
  else if(action==='csv-template')csvTemplate()
  else if(action==='toggle-result'){state.openResult=state.openResult===Number(btn.dataset.index)?-1:Number(btn.dataset.index);render();setTimeout(()=>document.querySelectorAll('.container-result')[Number(btn.dataset.index)]?.scrollIntoView({block:'nearest'}),30)}
  else if(action==='view-mode'){state.viewMode=id;render()}
  else if(action==='export-result-json')exportResultJson()
  else if(action==='export-result-csv')exportResultCsv()
  else if(action==='export-xlsx')exportXlsx()
  else if(action==='export-png')exportPng()
  else if(action==='export-pdf')exportPdf()
})

document.addEventListener('change',e=>{
  const t=e.target
  if(t.id==='project-file'&&t.files?.[0]){importProject(t.files[0]);t.value='';return}
  if(t.id==='csv-file'&&t.files?.[0]){importCsv(t.files[0]);t.value='';return}
  if(state.calculating)invalidateActiveCalculation()
  if(t.dataset.cargoQuantity){
    const id=t.dataset.cargoQuantity,q=Math.max(1,Math.floor(num(t.value,1)))
    state.cargo=state.cargo.map(c=>c.id===id?{...c,quantity:q}:c);state.result=null;persist();render();toast('수량을 수정했습니다.','success');return
  }
  if(t.dataset.cargoDirectionSimple){
    const id=t.dataset.cargoDirectionSimple,on=t.checked
    state.cargo=state.cargo.map(c=>c.id===id?{...c,orientationRules:on?orientationRulesForMode('all'):orientationRulesForMode('fixed'),rotation:'locked'}:c)
    state.result=null;persist();render();toast(`방향 변경 ${on?'허용':'해제'} · ${on?'최대 6방향을 자동 비교합니다.':'입력 방향만 사용합니다.'}`,'success');return
  }
  if(t.dataset.cargoOrientationMode){
    const id=t.dataset.cargoOrientationMode,mode=t.value
    state.cargo=state.cargo.map(c=>c.id===id?{...c,orientationRules:orientationRulesForMode(mode),rotation:'locked'}:c)
    state.result=null;persist();render();return
  }
  if(t.dataset.cargoStackRole){
    const id=t.dataset.cargoStackRole,role=t.value,flags=stackRoleFlags(role)
    state.cargo=state.cargo.map(c=>c.id===id?{...c,...flags,stackable:flags.canSupportCargo,maxStackLayers:role==='none'?1:Math.max(2,Number(c.maxStackLayers||2)),sameCargoStackOnly:role==='none'?c.sameCargoStackOnly:false}:c)
    state.result=null;persist();render();return
  }
  if(t.dataset.cargoStackSimple){
    const id=t.dataset.cargoStackSimple,on=t.checked
    state.cargo=state.cargo.map(c=>c.id===id?{...c,canBeStacked:on,canSupportCargo:on,stackable:on,maxStackLayers:on?Math.max(2,Number(c.maxStackLayers||2)):1,sameCargoStackOnly:on?false:c.sameCargoStackOnly}:c)
    state.result=null;persist();render();toast(`적층 ${on?'허용':'해제'} · 블록 최적화에 반영됩니다.`,'success');return
  }
  if(t.dataset.cargoOrientation){
    const id=t.dataset.cargoOrientation,rule=t.dataset.rule
    state.cargo=state.cargo.map(c=>c.id===id?{...c,orientationRules:{...(c.orientationRules||legacyOrientationRules(c.rotation)),[rule]:t.checked},rotation:'locked'}:c)
    state.result=null;persist();render();toast(`${t.checked?'허용':'해제'}: ${rule==='rotate90'?'바닥 90° 회전':rule==='layWidth'?'옆으로 눕힘':'앞으로 눕힘'}`,'success');return
  }
  if(t.dataset.cargoCapability){
    const id=t.dataset.cargoCapability,cap=t.dataset.capability,on=t.checked
    state.cargo=state.cargo.map(c=>{
      if(c.id!==id)return c
      const rules={...(c.orientationRules||legacyOrientationRules(c.rotation))}
      if(cap==='rotate')rules.rotate90=on
      if(cap==='lay'){rules.layWidth=on;rules.layLength=on}
      if(cap==='stack-on')return {...c,orientationRules:rules,rotation:'locked',canBeStacked:on,sameCargoStackOnly:on?false:c.sameCargoStackOnly}
      if(cap==='support')return {...c,orientationRules:rules,rotation:'locked',canSupportCargo:on,stackable:on,maxStackLayers:on?Math.max(2,Number(c.maxStackLayers||2)):Math.max(1,Number(c.maxStackLayers||1)),sameCargoStackOnly:on?false:c.sameCargoStackOnly}
      return {...c,orientationRules:rules,rotation:'locked'}
    })
    state.result=null;persist();render()
    const label=cap==='rotate'?'방향전환':cap==='lay'?'눕힘':cap==='stack-on'?'위 적층':'받침'
    toast(`${label} ${on?'허용':'해제'} · 다음 계산부터 반영됩니다.`,'success');return
  }
  if(t.dataset.setting){
    const k=t.dataset.setting
    if(k==='useInnerSpaces')state.settings={...state.settings,preset:'custom',useInnerSpaces:t.checked}
    else if(k==='blockContact')state.settings={...state.settings,preset:'custom',blockContact:t.checked}
    else if(k==='supportRatioPct')state.settings={...state.settings,preset:'custom',supportRatio:Math.min(1,Math.max(.5,(num(t.value,50))/100))}
    else state.settings={...state.settings,preset:'custom',[k]:Math.max(0,num(t.value))}
    state.result=null;persist();render()
  }
})

document.addEventListener('submit',e=>{
  const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(state.calculating)invalidateActiveCalculation();const fd=new FormData(form)
  if(form.dataset.form==='cargo'){
    const type=fd.get('packagingType'),base=packagePreset(type),item=normalizeCargoItem({id:fd.get('id'),name:String(fd.get('name')||'').trim(),length:num(fd.get('length')),width:num(fd.get('width')),height:num(fd.get('height')),weightKg:num(fd.get('weightKg')),quantity:num(fd.get('quantity')),rotation:'locked',orientationRules:orientationRulesForMode(String(fd.get('orientationMode')||'fixed')),canBeStacked:stackRoleFlags(String(fd.get('stackRole')||'none')).canBeStacked,canSupportCargo:stackRoleFlags(String(fd.get('stackRole')||'none')).canSupportCargo,stackable:stackRoleFlags(String(fd.get('stackRole')||'none')).canSupportCargo,maxStackLayers:Math.max(1,Math.floor(num(fd.get('maxStackLayers'),String(fd.get('stackRole')||'none')==='none'?1:2))),sameCargoStackOnly:fd.has('sameCargoStackOnly'),canBeNested:fd.has('canBeNested'),color:fd.get('color'),packaging:{...base,type,label:base.label,short:base.short,addLength:num(fd.get('packAddLength')),addWidth:num(fd.get('packAddWidth')),addHeight:num(fd.get('packAddHeight')),tareWeightKg:num(fd.get('packTareWeight')),memo:String(fd.get('packMemo')||''),overrideOuter:fd.has('overrideOuter'),outerLength:num(fd.get('outerLength')),outerWidth:num(fd.get('outerWidth')),outerHeight:num(fd.get('outerHeight'))},innerSpace:{enabled:fd.has('innerEnabled'),length:num(fd.get('innerLength')),width:num(fd.get('innerWidth')),height:num(fd.get('innerHeight')),access:fd.get('innerAccess'),maxPayloadKg:num(fd.get('innerMaxPayload'))}})
    const d=packedDimensions(item);if(!item.name||item.length<=0||item.width<=0||item.height<=0||item.quantity<=0||item.weightKg<0||num(item.packaging?.tareWeightKg)<0||num(item.packaging?.addLength)<0||num(item.packaging?.addWidth)<0||num(item.packaging?.addHeight)<0||d.length<=0||d.width<=0||d.height<=0)return toast('화물명, 제품/포장 치수, 중량, 수량을 확인하세요.','error');if(item.innerSpace.enabled&&(item.innerSpace.length>item.length||item.innerSpace.width>item.width||item.innerSpace.height>item.height))return toast('내부 사용가능 치수는 제품 외형을 초과할 수 없습니다.','error')
    const i=state.cargo.findIndex(x=>x.id===item.id);if(i>=0)state.cargo[i]=item;else state.cargo.push(item);state.modal=null;state.result=null;persist();render();toast('화물과 포장 정보가 저장되었습니다.','success')
  }else{
    const existing=state.containers.find(x=>x.id===fd.get('id')),L=num(fd.get('length')),W=num(fd.get('width')),H=num(fd.get('height')),item={id:fd.get('id'),name:String(fd.get('name')||'').trim(),shortName:existing?.shortName||'CUSTOM',length:L,width:W,height:H,doorWidth:num(fd.get('doorWidth'))||undefined,doorHeight:num(fd.get('doorHeight'))||undefined,maxPayloadKg:num(fd.get('maxPayloadKg')),nominalVolumeM3:boxVolumeM3(L,W,H),enabled:existing?.enabled??true,custom:existing?existing.custom===true:true};if(!item.name||L<=0||W<=0||H<=0||item.maxPayloadKg<=0)return toast('컨테이너 내측 치수와 적재중량을 확인하세요.','error');const i=state.containers.findIndex(x=>x.id===item.id);if(i>=0)state.containers[i]={...state.containers[i],...item};else state.containers.push(item);state.modal=null;state.result=null;persist();render();toast('컨테이너 규격이 저장되었습니다.','success')
  }
})

render()
